package main

import "fmt"

// Intersection of Two Arrays: вернуть уникальные общие элементы.
// Множество из первого массива, фильтруем второй.

func intersection(nums1, nums2 []int) []int {
	set := make(map[int]struct{}, len(nums1))
	for _, x := range nums1 {
		set[x] = struct{}{}
	}
	var res []int
	for _, x := range nums2 {
		if _, ok := set[x]; ok {
			res = append(res, x)
			delete(set, x) // чтобы не дублировать
		}
	}
	return res
}

func main() {
	fmt.Println(intersection([]int{1, 2, 2, 1}, []int{2, 2}))       // [2]
	fmt.Println(intersection([]int{4, 9, 5}, []int{9, 4, 9, 8, 4})) // [9 4]
}

package main

import (
	"fmt"
	"sync"
	"time"
)

// Задание 1: Fan-out / Fan-in

func gen(data []int, delay time.Duration) <-chan int {
	ch := make(chan int)
	go func() {
		defer close(ch)
		for _, val := range data {
			time.Sleep(delay)
			ch <- val
		}
	}()
	return ch
}

func merge(chans ...<-chan int) <-chan int {
	out := make(chan int)
	wg := sync.WaitGroup{}

	for _, ch := range chans {
		wg.Add(1)
		go func(c <-chan int) {
			defer wg.Done()
			for v := range c {
				out <- v
			}
		}(ch)
	}

	go func() {
		wg.Wait()
		close(out)
	}()

	return out
}

func main() {
	c1 := gen([]int{1, 2, 3}, 50*time.Millisecond)
	c2 := gen([]int{4, 5, 6}, 50*time.Millisecond)
	c3 := gen([]int{7, 8, 9}, 50*time.Millisecond)

	merged := merge(c1, c2, c3)
	for v := range merged {
		fmt.Println(v)
	}
}

