// Задание 1: Fan-Out / Fan-In
//
// Fan-Out: один источник → несколько воркеров
// Fan-In: несколько воркеров → один приёмник

use std::sync::mpsc;
#[allow(unused_imports)]
use std::thread::{self, JoinHandle};

fn producer(tx: mpsc::Sender<i32>, count: i32) {
    for i in 0..count {
        tx.send(i).unwrap();
    }
    // tx дропается здесь → канал закрывается
}

#[allow(dead_code)]
fn worker(id: i32, rx: mpsc::Receiver<i32>, tx: mpsc::Sender<i32>) {
    for val in rx {
        let result = val * id;
        println!("worker {} processed {} -> {}", id, val, result);
        tx.send(result).unwrap();
    }
}

fn fan_out_fan_in(data_count: i32, worker_count: i32) -> Vec<i32> {
    // Канал: producer → воркеры
    let (prod_tx, prod_rx) = mpsc::channel();

    // Канал: воркеры → collector
    let (work_tx, work_rx) = mpsc::channel();

    // Запускаем producer
    let prod_handle = thread::spawn(move || {
        producer(prod_tx, data_count);
    });

    // Fan-Out: раздаём prod_rx между воркерами через Arc<Mutex>
    let shared_rx = std::sync::Arc::new(std::sync::Mutex::new(prod_rx));

    let mut handles: Vec<thread::JoinHandle<()>> = Vec::new();

    for _id in 0..worker_count {
        let rx_clone = shared_rx.clone();
        let tx_clone = work_tx.clone();

        let handle = thread::spawn(move || {
            loop {
                let msg = {
                    let lock = rx_clone.lock().unwrap();
                    lock.try_recv()
                };
                match msg {
                    Ok(val) => {
                        let result = val * val;
                        tx_clone.send(result).unwrap();
                    }
                    Err(mpsc::TryRecvError::Empty) => {
                        // канал пуст, попробуем ещё
                        thread::sleep(std::time::Duration::from_millis(1));
                    }
                    Err(mpsc::TryRecvError::Disconnected) => break,
                }
            }
        });
        handles.push(handle);
    }

    // Дропаем оригинальный tx чтобы work_rx мог завершиться
    drop(work_tx);

    // Fan-In: собираем результаты
    prod_handle.join().unwrap();
    for h in handles {
        h.join().unwrap();
    }

    let mut results: Vec<i32> = Vec::new();
    for val in work_rx {
        results.push(val);
    }

    results.sort();
    results
}

fn main() {
    let results = fan_out_fan_in(10, 3);
    println!("results: {:?}", results);
    println!("count: {}", results.len());
}

