package main

import (
	"context"
	"errors"
	"fmt"
	"math/rand"
	"time"
)

// Задание 2: Context с таймаутом

func longOperation() int {
	time.Sleep(time.Duration(rand.Intn(5)) * time.Second)
	return 42
}

func callWithTimeout(ctx context.Context) (int, error) {
	ch := make(chan int, 1)
	go func() {
		ch <- longOperation()
	}()

	select {
	case <-ctx.Done():
		return 0, errors.New("timeout exceeded")
	case v := <-ch:
		return v, nil
	}
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	res, err := callWithTimeout(ctx)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	fmt.Println("Result:", res)
}

