// Задание 2: Таймаут и отмена (аналог context.WithTimeout в Go)
//
// В Rust нет context — используем каналы и Duration для таймаутов.

use std::sync::mpsc;
use std::thread;
use std::time::Duration;

fn slow_operation(duration_ms: u64) -> String {
    thread::sleep(Duration::from_millis(duration_ms));
    format!("done after {}ms", duration_ms)
}

// Выполнить операцию с таймаутом
fn with_timeout<T: Send + 'static>(
    timeout: Duration,
    f: impl FnOnce() -> T + Send + 'static,
) -> Result<T, &'static str> {
    let (tx, rx) = mpsc::channel();

    thread::spawn(move || {
        let result = f();
        let _ = tx.send(result); // ignore error if receiver dropped
    });

    match rx.recv_timeout(timeout) {
        Ok(val) => Ok(val),
        Err(mpsc::RecvTimeoutError::Timeout) => Err("operation timed out"),
        Err(mpsc::RecvTimeoutError::Disconnected) => Err("channel disconnected"),
    }
}

// Отмена через канал-флаг (аналог ctx.Done())
fn cancellable_work(cancel_rx: mpsc::Receiver<()>, result_tx: mpsc::Sender<i32>) {
    let mut sum = 0;
    for i in 0..100 {
        // Проверяем отмену
        match cancel_rx.try_recv() {
            Ok(_) | Err(mpsc::TryRecvError::Disconnected) => {
                println!("cancelled at iteration {}", i);
                return;
            }
            Err(mpsc::TryRecvError::Empty) => {} // канал пуст — продолжаем
        }

        sum += i;
        thread::sleep(Duration::from_millis(50));
    }
    let _ = result_tx.send(sum);
}

fn main() {
    // --- Таймаут: успех ---
    println!("=== timeout: success ===");
    let result = with_timeout(Duration::from_millis(500), || slow_operation(100));
    println!("result: {:?}", result);

    // --- Таймаут: превышен ---
    println!("\n=== timeout: exceeded ===");
    let result = with_timeout(Duration::from_millis(100), || slow_operation(500));
    println!("result: {:?}", result);

    // --- Отмена через канал ---
    println!("\n=== cancellation ===");
    let (cancel_tx, cancel_rx) = mpsc::channel();
    let (result_tx, result_rx) = mpsc::channel();

    let handle = thread::spawn(move || {
        cancellable_work(cancel_rx, result_tx);
    });

    // Даём поработать 200ms, потом отменяем
    thread::sleep(Duration::from_millis(200));
    cancel_tx.send(()).unwrap(); // отправляем сигнал отмены

    handle.join().unwrap();

    match result_rx.try_recv() {
        Ok(val) => println!("got result: {}", val),
        Err(_) => println!("no result (cancelled)"),
    }
}

