package main

import (
	"context"
	"fmt"
	"math/rand"
	"sync"
	"time"
)

// Задание 3: Worker Pool с контекстом

func process(v int) int {
	time.Sleep(time.Duration(rand.Intn(100)) * time.Millisecond)
	return v * 10
}

func processWithCtx(ctx context.Context, v int) (int, bool) {
	ch := make(chan int, 1)
	go func() {
		ch <- process(v)
	}()

	select {
	case <-ctx.Done():
		return 0, false
	case res := <-ch:
		return res, true
	}
}

func workerPool(ctx context.Context, in <-chan int, out chan<- int, workers int) {
	var wg sync.WaitGroup

	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					return
				case v, ok := <-in:
					if !ok {
						return
					}
					res, ok := processWithCtx(ctx, v)
					if !ok {
						return
					}
					select {
					case out <- res:
					case <-ctx.Done():
						return
					}
				}
			}
		}()
	}

	wg.Wait()
}

func main() {
	in := make(chan int)
	out := make(chan int)

	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()

	go func() {
		defer close(in)
		for i := 1; i <= 20; i++ {
			select {
			case <-ctx.Done():
				return
			case in <- i:
			}
		}
	}()

	go func() {
		defer close(out)
		workerPool(ctx, in, out, 4)
	}()

	for v := range out {
		fmt.Println(v)
	}
}

