// Задание 3: Worker Pool (пул потоков)

use std::sync::{mpsc, Arc, Mutex};
use std::thread;

type Job = Box<dyn FnOnce() + Send + 'static>;

struct WorkerPool {
    workers: Vec<Worker>,
    sender: Option<mpsc::Sender<Job>>,
}

struct Worker {
    id: usize,
    handle: Option<thread::JoinHandle<()>>,
}

impl Worker {
    fn new(id: usize, receiver: Arc<Mutex<mpsc::Receiver<Job>>>) -> Worker {
        let handle = thread::spawn(move || {
            loop {
                let job = {
                    let lock = receiver.lock().unwrap();
                    lock.recv() // recv() блокируется пока нет задачи
                };
                match job {
                    Ok(job) => {
                        println!("worker {} got a job", id);
                        job(); // вызываем замыкание
                    }
                    Err(_) => {
                        // канал закрыт — выходим
                        println!("worker {} shutting down", id);
                        break;
                    }
                }
            }
        });
        Worker {
            id,
            handle: Some(handle),
        }
    }
}

impl WorkerPool {
    fn new(size: usize) -> WorkerPool {
        let (tx, rx) = mpsc::channel();
        let rx = Arc::new(Mutex::new(rx));

        let mut workers = Vec::with_capacity(size);

        for id in 0..size {
            workers.push(Worker::new(id, Arc::clone(&rx)));
        }

        WorkerPool {
            workers,
            sender: Some(tx),
        }
    }

    fn execute<F>(&self, f: F)
    where
        F: FnOnce() + Send + 'static,
    {
        let job = Box::new(f);
        self.sender.as_ref().unwrap().send(job).unwrap();
    }
}

impl Drop for WorkerPool {
    fn drop(&mut self) {
        // Дропаем sender → закрываем канал → воркеры выйдут из loop
        drop(self.sender.take());

        for worker in &mut self.workers {
            if let Some(handle) = worker.handle.take() {
                handle.join().unwrap();
            }
        }
        println!("all workers stopped");
    }
}

fn main() {
    let pool = WorkerPool::new(4);

    for i in 0..8 {
        pool.execute(move || {
            println!("  task {} running on {:?}", i, thread::current().id());
            thread::sleep(std::time::Duration::from_millis(100));
            println!("  task {} done", i);
        });
    }

    // Небольшая пауза чтобы задачи начали выполняться
    thread::sleep(std::time::Duration::from_millis(300));

    // pool дропается здесь → graceful shutdown
    println!("dropping pool...");
}

