# Задание 6: threading + Queue — воркер-пул

import threading
import queue
import time
from typing import Callable, Any

# --- Потокобезопасный счётчик ---

class AtomicCounter:
    def __init__(self):
        self._value = 0
        self._lock = threading.Lock()

    def increment(self) -> int:
        with self._lock:
            self._value += 1
            return self._value

    @property
    def value(self) -> int:
        with self._lock:
            return self._value

# --- Worker Pool ---

class WorkerPool:
    def __init__(self, num_workers: int, queue_size: int = 0):
        self.tasks: queue.Queue = queue.Queue(maxsize=queue_size)
        self.results: queue.Queue = queue.Queue()
        self.workers: list[threading.Thread] = []
        self.counter = AtomicCounter()
        self._shutdown = threading.Event()  # Event для остановки

        for i in range(num_workers):
            t = threading.Thread(
                target=self._worker,
                args=(i,),
                daemon=True,
            )
            self.workers.append(t)
            t.start()

    def _worker(self, worker_id: int):
        while not self._shutdown.is_set():
            try:
                func, args, kwargs = self.tasks.get(timeout=0.1)
            except queue.Empty:
                continue

            try:
                result = func(*args, **kwargs)
                self.results.put(( worker_id, result, None))
            except Exception as e:
                self.results.put((worker_id, None, e))
            finally:
                self.counter.increment()
                self.tasks.task_done()

    def submit(self, func: Callable, *args, **kwargs):
        self.tasks.put(( func, args, kwargs))

    def shutdown(self, wait: bool = True):
        if wait:
            self.tasks.join()  # ждём пока все задачи обработаны
        self._shutdown.set()
        for t in self.workers:
            t.join(timeout=5.0)

    def get_results(self) -> list[Any]:
        results = []
        while not self.results.empty():
            results.append(self.results.get())
        return results

# --- Использование ---

def heavy_task(n: int) -> int:
    """Имитация тяжёлой задачи"""
    time.sleep(0.1)
    if n == 7:
        raise ValueError("unlucky number!")
    return n * 2

if __name__ == "__main__":
    pool = WorkerPool(num_workers=4, queue_size=100)

    start = time.perf_counter()

    # Отправляем 10 задач
    for i in range(10):
        pool.submit(heavy_task, i)

    pool.shutdown()

    elapsed = time.perf_counter() - start
    print(f"completed in {elapsed:.2f}s")
    print(f"tasks processed: {pool.counter.value}")

    for worker_id, result, error in pool.get_results():
        if error is not None:
            print(f"worker {worker_id}: ERROR — {error}")
        else:
            print(f"worker {worker_id}: result = {result}")

