package main

import (
	"fmt"
	"sync"
	"time"
)

// Задание 6: Семафор через канал

func main() {
	urls := []string{"url1", "url2", "url3", "url4", "url5", "url6", "url7", "url8", "url9", "url10"}
	results := make(map[string]int)
	mu := sync.Mutex{}
	wg := sync.WaitGroup{}

	// Семафор на 3 одновременных горутины
	sema := make(chan int, 3)

	wg.Add(len(urls))
	for _, url := range urls {
		url := url
		sema <- 1
		go func() {
			defer func() {
				<-sema
				wg.Done()
			}()

			// Симуляция HTTP запроса
			time.Sleep(100 * time.Millisecond)
			code := 200

			mu.Lock()
			results[url] = code
			mu.Unlock()
		}()
	}

	wg.Wait()
	fmt.Println("Total results:", len(results))
}

