// Задание 6: Семафор (ограничение параллелизма)
//
// В Rust нет встроенного семафора — строим из Mutex + Condvar.

use std::sync::{Arc, Condvar, Mutex};
use std::thread;
use std::time::{Duration, Instant};

struct Semaphore {
    mutex: Mutex<usize>,
    condvar: Condvar,
    max_permits: usize,
}

impl Semaphore {
    fn new(max_permits: usize) -> Self {
        Semaphore {
            mutex: Mutex::new(0),
            condvar: Condvar::new(),
            max_permits,
        }
    }

    fn acquire(&self) {
        let mut count = self.mutex.lock().unwrap();
        while *count >= self.max_permits {
            count = self.condvar.wait(count).unwrap();
        }
        *count += 1;
    }

    fn release(&self) {
        let mut count = self.mutex.lock().unwrap();
        *count -= 1;
        self.condvar.notify_one(); // будим одного ждущего
    }
}

fn limited_task(id: i32, sem: &Semaphore) {
    sem.acquire();
    let start = Instant::now();
    println!("[{:>3}ms] task {} started", start.elapsed().as_millis(), id);

    thread::sleep(Duration::from_millis(200));

    println!("[{:>3}ms] task {} done", start.elapsed().as_millis(), id);
    sem.release();
}

fn main() {
    let sem = Arc::new(Semaphore::new(3)); // максимум 3 одновременно

    let mut handles = Vec::new();

    let start = Instant::now();

    for i in 0..10 {
        let sem_clone = Arc::clone(&sem);
        let handle = thread::spawn(move || {
            limited_task(i, &sem_clone);
        });
        handles.push(handle);
    }

    for h in handles {
        h.join().unwrap();
    }

    println!("\nall done in {:?}", start.elapsed());
    // 10 задач по 200ms, семафор 3 → ~800ms (ceil(10/3) * 200)
}

