package main

import (
	"fmt"
)

// Задание 7: Pipeline (конвейер каналов)

func generate(nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for _, n := range nums {
			out <- n
		}
	}()
	return out
}

func square(in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for v := range in {
			out <- v * v
		}
	}()
	return out
}

func double(in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for v := range in {
			out <- v * 2
		}
	}()
	return out
}

func main() {
	// Pipeline: generate -> square -> double
	nums := generate(1, 2, 3, 4, 5)
	squared := square(nums)
	doubled := double(squared)

	for v := range doubled {
		fmt.Println(v) // 2, 8, 18, 32, 50
	}
}

