// Задание 7: Pipeline (конвейер обработки данных)
//
// Аналог Go pipeline: generator → stage1 → stage2 → consumer
// В Rust используем mpsc каналы между потоками.

use std::sync::mpsc;
use std::thread;

fn generator(data: Vec<i32>) -> mpsc::Receiver<i32> {
    let (tx, rx) = mpsc::channel();

    thread::spawn(move || {
        for val in data {
            tx.send(val).unwrap();
        }
        // tx дропается → канал закрывается
    });

    rx
}

fn filter_even(input: mpsc::Receiver<i32>) -> mpsc::Receiver<i32> {
    let (tx, rx) = mpsc::channel();

    thread::spawn(move || {
        for val in input {
            if val % 2 == 0 {
                tx.send(val).unwrap();
            }
        }
    });

    rx
}

fn multiply(input: mpsc::Receiver<i32>, factor: i32) -> mpsc::Receiver<i32> {
    let (tx, rx) = mpsc::channel();

    thread::spawn(move || {
        for val in input {
            tx.send(val * factor).unwrap();
        }
    });

    rx
}

fn to_string_stage(input: mpsc::Receiver<i32>) -> mpsc::Receiver<String> {
    let (tx, rx) = mpsc::channel();

    thread::spawn(move || {
        for val in input {
            let s = format!("result={}", val);
            tx.send(s).unwrap();
        }
    });

    rx
}

// Ветвление: один вход → два выхода (tee)
fn tee(input: mpsc::Receiver<i32>) -> (mpsc::Receiver<i32>, mpsc::Receiver<i32>) {
    let (tx1, rx1) = mpsc::channel();
    let (tx2, rx2) = mpsc::channel();

    thread::spawn(move || {
        for val in input {
            let _ = tx1.send(val);
            let _ = tx2.send(val);
        }
    });

    (rx1, rx2)
}

// Merge: два входа → один выход
fn merge(rx1: mpsc::Receiver<i32>, rx2: mpsc::Receiver<i32>) -> mpsc::Receiver<i32> {
    let (tx, rx) = mpsc::channel();

    let tx2 = tx.clone();

    thread::spawn(move || {
        for val in rx1 {
            tx.send(val).unwrap();
        }
    });

    thread::spawn(move || {
        for val in rx2 {
            tx2.send(val).unwrap();
        }
    });

    rx
}

fn main() {
    // Простой pipeline: генерация → фильтр чётных → умножение на 10 → строка
    println!("=== Simple Pipeline ===");
    let data = (1..=10).collect();
    let stage1 = generator(data);
    let stage2 = filter_even(stage1);
    let stage3 = multiply(stage2, 10);
    let stage4 = to_string_stage(stage3);

    for s in stage4 {
        println!("  {}", s);
    }

    // Tee + Merge
    println!("\n=== Tee + Merge ===");
    let source = generator(vec![1, 2, 3, 4, 5]);
    let (branch1, branch2) = tee(source);

    let doubled = multiply(branch1, 2);
    let tripled = multiply(branch2, 3);

    let merged = merge(doubled, tripled);

    let mut results: Vec<i32> = merged.iter().collect();
    results.sort();
    println!("  merged: {:?}", results);
}

