package main

import (
	"fmt"
	"time"
)

// Задание 11: Select и два канала

func main() {
	ch1 := make(chan string)
	ch2 := make(chan string)

	go func() {
		time.Sleep(100 * time.Millisecond)
		ch1 <- "from channel 1"
	}()

	go func() {
		time.Sleep(200 * time.Millisecond)
		ch2 <- "from channel 2"
	}()

	done := 0
	for done < 2 {
		select {
		case msg1 := <-ch1:
			fmt.Println(msg1)
			done++
		case msg2 := <-ch2:
			fmt.Println(msg2)
			done++
		case <-time.After(time.Second):
			fmt.Println("timeout!")
			done = 2
		}
	}
}

