// Задание 13: Ручная реализация аналога errgroup

type ErrGroup struct {
	wg     sync.WaitGroup
	mu     sync.Mutex
	err    error
	ctx    context.Context
	cancel context.CancelFunc
}

func NewErrGroup(ctx context.Context) *ErrGroup {
	ctx, cancel := context.WithCancel(ctx)
	return &ErrGroup{
		ctx:    ctx,
		cancel: cancel,
	}
}

func (g *ErrGroup) Go(f func() error) {
	g.wg.Add(1)
	go func() {
		defer g.wg.Done()
		if err := f(); err != nil {
			g.mu.Lock()
			if g.err == nil {
				g.err = err
			}
			g.mu.Unlock()
			g.cancel()
		}
	}()
}

func (g *ErrGroup) Wait() error {
	g.wg.Wait()
	g.cancel()
	return g.err
}

func fetchData(id int) error {
	time.Sleep(time.Duration(rand.Intn(200)) * time.Millisecond)
	if id == 3 {
		return fmt.Errorf("fetch failed for id=%d", id)
	}
	fmt.Printf("fetched id=%d\n", id)
	return nil
}

func main() {
	ctx := context.Background()
	g := NewErrGroup(ctx)

	for i := 1; i <= 5; i++ {
		id := i
		g.Go(func() error {
			return fetchData(id)
		})
	}

	if err := g.Wait(); err != nil {
		fmt.Println("Error:", err)
	} else {
		fmt.Println("All done!")
	}
}

