// Задание 17: Thread-safe очередь с ограничением

type BoundedQueue struct {
	mu       sync.Mutex
	notEmpty *sync.Cond
	notFull  *sync.Cond
	items    []int
	cap      int
}

func NewBoundedQueue(capacity int) *BoundedQueue {
	q := &BoundedQueue{
		items: make([]int, 0, capacity),
		cap:   capacity,
	}
	q.notEmpty = sync.NewCond(&q.mu)
	q.notFull = sync.NewCond(&q.mu)
	return q
}

func (q *BoundedQueue) Enqueue(val int) {
	q.mu.Lock()
	defer q.mu.Unlock()

	for len(q.items) >= q.cap {
		q.notFull.Wait()
	}

	q.items = append(q.items, val)
	q.notEmpty.Signal()
}

func (q *BoundedQueue) Dequeue() int {
	q.mu.Lock()
	defer q.mu.Unlock()

	for len(q.items) == 0 {
		q.notEmpty.Wait()
	}

	val := q.items[0]
	q.items = q.items[1:]
	q.notFull.Signal()
	return val
}

func (q *BoundedQueue) Len() int {
	q.mu.Lock()
	defer q.mu.Unlock()
	return len(q.items)
}

func main() {
	q := NewBoundedQueue(5)
	var wg sync.WaitGroup

	// Продюсеры
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for j := 0; j < 5; j++ {
				val := id*100 + j
				q.Enqueue(val)
				fmt.Printf("producer %d: enqueued %d\n", id, val)
			}
		}(i)
	}

	// Консьюмеры
	for i := 0; i < 2; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for j := 0; j < 7; j++ {
				val := q.Dequeue()
				fmt.Printf("consumer %d: dequeued %d\n", id, val)
			}
		}(i)
	}

	// +1 консьюмер на остаток
	wg.Add(1)
	go func() {
		defer wg.Done()
		val := q.Dequeue()
		fmt.Printf("extra consumer: dequeued %d\n", val)
	}()

	wg.Wait()
	fmt.Println("Queue len:", q.Len())
}

