// Задание 19: Pipeline с контекстом (gen -> filter -> square -> print)

func gen(ctx context.Context, nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for _, n := range nums {
			select {
			case <-ctx.Done():
				return
			case out <- n:
			}
		}
	}()
	return out
}

func filter(ctx context.Context, in <-chan int, predicate func(int) bool) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for {
			select {
			case <-ctx.Done():
				return
			case v, ok := <-in:
				if !ok {
					return
				}
				if predicate(v) {
					select {
					case <-ctx.Done():
						return
					case out <- v:
					}
				}
			}
		}
	}()
	return out
}

func sq(ctx context.Context, in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for {
			select {
			case <-ctx.Done():
				return
			case v, ok := <-in:
				if !ok {
					return
				}
				select {
				case <-ctx.Done():
					return
				case out <- v * v:
				}
			}
		}
	}()
	return out
}

func sink(ctx context.Context, in <-chan int) {
	for {
		select {
		case <-ctx.Done():
			fmt.Println("sink: cancelled")
			return
		case v, ok := <-in:
			if !ok {
				fmt.Println("sink: channel closed")
				return
			}
			fmt.Println("result:", v)
		}
	}
}

func main() {
	rand.Seed(time.Now().UnixNano())

	ctx, cancel := context.WithTimeout(context.Background(), 500*time.Millisecond)
	defer cancel()

	// Генерируем числа 1..20
	nums := make([]int, 20)
	for i := range nums {
		nums[i] = i + 1
	}

	// Pipeline: gen -> filter(чётные) -> square -> print
	source := gen(ctx, nums...)
	evens := filter(ctx, source, func(n int) bool {
		return n%2 == 0
	})
	squared := sq(ctx, evens)
	sink(ctx, squared)
}

