// Задание 20: Конкурентная генерация уникальных ID + дедупликация

type SafeSet struct {
	mu   sync.RWMutex
	data map[int]struct{}
}

func NewSafeSet() *SafeSet {
	return &SafeSet{
		data: make(map[int]struct{}),
	}
}

func (s *SafeSet) Add(val int) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, exists := s.data[val]; exists {
		return false
	}
	s.data[val] = struct{}{}
	return true
}

func (s *SafeSet) Len() int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return len(s.data)
}

func producer(out chan<- int, count int, maxVal int, wg *sync.WaitGroup) {
	defer wg.Done()
	for i := 0; i < count; i++ {
		val := rand.Intn(maxVal)
		out <- val
		time.Sleep(time.Duration(rand.Intn(5)) * time.Millisecond)
	}
}

func deduplicator(in <-chan int, out chan<- int, set *SafeSet, wg *sync.WaitGroup) {
	defer wg.Done()
	for val := range in {
		if set.Add(val) {
			out <- val
		}
	}
}

func collector(in <-chan int, results *[]int, mu *sync.Mutex, done chan struct{}) {
	for val := range in {
		mu.Lock()
		*results = append(*results, val)
		mu.Unlock()
	}
	close(done)
}

func main() {
	rand.Seed(time.Now().UnixNano())

	raw := make(chan int, 100)
	unique := make(chan int, 100)
	done := make(chan struct{})

	set := NewSafeSet()
	results := make([]int, 0)
	var mu sync.Mutex

	// Запускаем collector
	go collector(unique, &results, &mu, done)

	// Запускаем дедупликаторов
	var dedupWg sync.WaitGroup
	dedupWg.Add(2)
	for i := 0; i < 2; i++ {
		go deduplicator(raw, unique, set, &dedupWg)
	}

	// Запускаем продюсеров
	var prodWg sync.WaitGroup
	prodWg.Add(4)
	for i := 0; i < 4; i++ {
		go producer(raw, 50, 20, &prodWg)
	}

	// Ждём продюсеров -> закрываем raw
	prodWg.Wait()
	close(raw)

	// Ждём дедупликаторов -> закрываем unique
	dedupWg.Wait()
	close(unique)

	// Ждём collector
	<-done

	fmt.Println("Total unique:", len(results))
	fmt.Println("Set size:", set.Len())
	fmt.Println("Values:", results)
}

