	"sync"
	"time"
)

// === ЗАДАНИЕ 1: Generator ===

func Generator(ctx context.Context, data []int) <-chan int {
	out := make(chan int) // 1. создай канал

	go func() {
		defer close(out) // 2. закрой канал при выходе
		for _, v := range data {
			select {
			case out <- v: // 3. отправь v в out
			case <-ctx.Done(): // 4. выйди при отмене ctx
				return
			}
		}
	}()

	return out // 5. верни канал
}

// === ЗАДАНИЕ 2: Worker Pool (processParallel) ===

func processParallel(ctx context.Context, in <-chan int, workers int) <-chan int {
	out := make(chan int)
	wg := &sync.WaitGroup{} // 6. создай WaitGroup

	for i := 0; i < workers; i++ {
		wg.Add(1) // 7. добавь 1 к WaitGroup
		go func() {
			defer wg.Done() // 8. уменьши WaitGroup при выходе
			for {
				select {
				case <-ctx.Done(): // 9. выйди при отмене ctx
					return
				case v, ok := <-in: // 10. прочитай из in
					if !ok {
						return
					}
					result := v * 2
					select {
					case out <- result: // 11. отправь result в out
					case <-ctx.Done(): // 12. выйди при отмене ctx
						return
					}
				}
			}
		}()
	}

	go func() {
		wg.Wait()  // 13. дождись завершения всех воркеров
		close(out) // 14. закрой out
	}()

	return out
}

// === ЗАДАНИЕ 3: Fan-In (merge) ===

func merge(ctx context.Context, channels ...<-chan int) <-chan int {
	out := make(chan int)
	wg := &sync.WaitGroup{} // 15. создай WaitGroup

	for _, ch := range channels {
		wg.Add(1) // 16. добавь 1 к WaitGroup
		go func(c <-chan int) {
			defer wg.Done() // 17. уменьши WaitGroup при выходе
			for {
				select {
				case <-ctx.Done(): // 18. выйди при отмене ctx
					return
				case v, ok := <-c: // 19. прочитай из c
					if !ok {
						return
					}
					select {
					case out <- v: // 20. отправь v в out
					case <-ctx.Done(): // 21. выйди при отмене ctx
						return
					}
				}
			}
		}(ch) // 22. передай ch в горутину
	}

	go func() {
		wg.Wait()  // 23. дождись завершения
		close(out) // 24. закрой out
	}()

	return out
}

// === ЗАДАНИЕ 4: main ===

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second) // 25. таймаут 5 секунд
	defer cancel()                                                          // 26. отложи вызов cancel

	ch1 := Generator(ctx, []int{1, 2, 3, 4, 5})
	ch2 := Generator(ctx, []int{6, 7, 8, 9, 10})

	processed1 := processParallel(ctx, ch1, 3)
	processed2 := processParallel(ctx, ch2, 3)

	merged := merge(ctx, processed1, processed2) // 27. передай оба канала

	for v := range merged { // 28. читай из merged
		fmt.Println(v)
	}
	fmt.Println("done")
}

