// Задание 4: Потокобезопасная HashMap (аналог sync.Map / concurrent map в Go)

use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::thread;

struct ConcurrentMap<V: Clone + Send> {
    data: Arc<RwLock<HashMap<String, V>>>,
}

impl<V: Clone + Send + 'static> ConcurrentMap<V> {
    fn new() -> Self {
        ConcurrentMap {
            data: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    fn insert(&self, key: String, value: V) {
        let mut map = self.data.write().unwrap();
        map.insert(key, value);
    }

    fn get(&self, key: &str) -> Option<V> {
        let map = self.data.read().unwrap(); // read lock
        map.get(key).cloned()
    }

    fn delete(&self, key: &str) -> Option<V> {
        let mut map = self.data.write().unwrap();
        map.remove(key)
    }

    fn len(&self) -> usize {
        let map = self.data.read().unwrap();
        map.len()
    }

    fn contains(&self, key: &str) -> bool {
        let map = self.data.read().unwrap();
        map.contains_key(key)
    }

    fn keys(&self) -> Vec<String> {
        let map = self.data.read().unwrap();
        map.keys().cloned().collect()
    }

    // Нужен clone для многопоточности
    fn clone(&self) -> ConcurrentMap<V> {
        ConcurrentMap {
            data: Arc::clone(&self.data),
        }
    }
}

fn main() {
    let map = ConcurrentMap::<i32>::new();

    let mut handles = Vec::new();

    // 4 потока пишут
    for t in 0..4 {
        let map_clone = map.clone();
        let handle = thread::spawn(move || {
            for i in 0..5 {
                let key = format!("t{}_key{}", t, i);
                map_clone.insert(key.clone(), t * 100 + i);
                println!("  inserted {}", key);
            }
        });
        handles.push(handle);
    }

    for h in handles {
        h.join().unwrap();
    }

    println!("\nmap size: {}", map.len());
    println!("contains t0_key0: {}", map.contains("t0_key0"));
    println!("get t2_key3: {:?}", map.get("t2_key3"));
    println!("keys count: {}", map.keys().len());

    // Удаление
    let removed = map.delete("t0_key0");
    println!("removed t0_key0: {:?}", removed);
    println!("map size after delete: {}", map.len());
}

