package main

import "fmt"

// Задание 5: Реализация стека

type Stack struct {
	items []string
}

func (s *Stack) Push(data string) {
	s.items = append(s.items, data)
}

func (s *Stack) Pop() (string, bool) {
	if s.IsEmpty() {
		return "", false
	}
	top := s.items[len(s.items)-1]
	s.items = s.items[:len(s.items)-1]
	return top, true
}

func (s *Stack) IsEmpty() bool {
	return len(s.items) == 0
}

func (s *Stack) Top() (string, bool) {
	if s.IsEmpty() {
		return "", false
	}
	return s.items[len(s.items)-1], true
}

func main() {
	s := Stack{}
	s.Push("A")
	s.Push("B")
	s.Push("C")

	top, _ := s.Top()
	fmt.Println("Top:", top) // C

	val, _ := s.Pop()
	fmt.Println("Popped:", val) // C

	top, _ = s.Top()
	fmt.Println("Top after pop:", top) // B
}

