// Задание 5: Generic Stack

#[derive(Debug)]
struct Stack<T> {
    items: Vec<T>,
    max_size: usize,
}

#[derive(Debug)]
enum StackError {
    Overflow,
    Underflow,
}

impl std::fmt::Display for StackError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            StackError::Overflow => write!(f, "stack overflow"),
            StackError::Underflow => write!(f, "stack underflow"),
        }
    }
}

impl<T: std::fmt::Debug> Stack<T> {
    fn new(max_size: usize) -> Self {
        Stack {
            items: Vec::new(),
            max_size: max_size,
        }
    }

    fn push(&mut self, item: T) -> Result<(), StackError> {
        if self.items.len() >= self.max_size {
            return Err(StackError::Overflow);
        }
        self.items.push(item);
        Ok(())
    }

    fn pop(&mut self) -> Result<T, StackError> {
        self.items.pop().ok_or(StackError::Underflow)
    }

    fn peek(&self) -> Option<&T> {
        self.items.last()
    }

    fn is_empty(&self) -> bool {
        self.items.is_empty()
    }

    fn len(&self) -> usize {
        self.items.len()
    }

    fn clear(&mut self) {
        self.items.clear();
    }
}

// Итератор для Stack — достаём с вершины
impl<T: std::fmt::Debug> Iterator for Stack<T> {
    type Item = T;
    fn next(&mut self) -> Option<T> {
        self.items.pop()
    }
}

// Создание стека из вектора
impl<T: std::fmt::Debug> From<Vec<T>> for Stack<T> {
    fn from(items: Vec<T>) -> Self {
        let max_size = items.len() * 2;
        Stack {
            items,
            max_size: max_size,
        }
    }
}

fn main() {
    let mut stack = Stack::new(5);

    // Push
    for i in 1..=5 {
        stack.push(i).unwrap();
        println!("pushed {}, len={}", i, stack.len());
    }

    // Overflow
    match stack.push(6) {
        Ok(_) => println!("pushed 6"),
        Err(e) => println!("error: {}", e),
    }

    // Peek
    println!("\npeek: {:?}", stack.peek());

    // Pop
    while !stack.is_empty() {
        let val = stack.pop().unwrap();
        println!("popped: {}", val);
    }

    // Underflow
    match stack.pop() {
        Ok(v) => println!("got: {}", v),
        Err(e) => println!("error: {}", e),
    }

    // From vec
