package main

import (
	"fmt"
	"hash/fnv"
	"sync"
)

// Задание 10: Thread-safe шардированный кеш

type shard struct {
	mu   sync.RWMutex
	data map[string]string
}

func newShard() *shard {
	return &shard{data: map[string]string{}}
}

func (s *shard) set(key, value string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.data[key] = value
}

func (s *shard) get(key string) (string, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.data[key]
	return v, ok
}

type ShardedCache struct {
	shards []*shard
	n      int
}

func NewCache(numShards int) *ShardedCache {
	shards := make([]*shard, numShards)
	for i := range shards {
		shards[i] = newShard()
	}
	return &ShardedCache{shards: shards, n: numShards}
}

func (c *ShardedCache) shardFor(key string) *shard {
	h := fnv.New64()
	h.Write([]byte(key))
	idx := int(h.Sum64() % uint64(c.n))
	return c.shards[idx]
}

func (c *ShardedCache) Set(key, value string) {
	s := c.shardFor(key)
	s.set(key, value)
}

func (c *ShardedCache) Get(key string) (string, bool) {
	s := c.shardFor(key)
	return s.get(key)
}

func main() {
	cache := NewCache(4)

	var wg sync.WaitGroup
	// Параллельная запись
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			key := fmt.Sprintf("key_%d", i)
			val := fmt.Sprintf("val_%d", i)
			cache.Set(key, val)
		}(i)
	}
	wg.Wait()

	// Проверка
	if v, ok := cache.Get("key_42"); ok {
		fmt.Println("Found:", v)
	}
}

