// Задание 10: Sharded Cache (аналог Go sharded cache с RWMutex)
//
// Шардирование: вместо одного большого лока — N маленьких.
// Ключ хешируется → выбирается шард → лочится только он.

use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::sync::{Arc, RwLock};
use std::thread;
use std::time::{Duration, Instant};

const NUM_SHARDS: usize = 16;

struct Shard<V> {
    data: RwLock<HashMap<String, V>>,
}

struct ShardedCache<V: Clone + Send + Sync> {
    shards: Vec<Shard<V>>,
}

impl<V: Clone + Send + Sync> ShardedCache<V> {
    fn new() -> Self {
        let mut shards = Vec::with_capacity(NUM_SHARDS);
        for _ in 0..NUM_SHARDS {
            shards.push(Shard {
                data: RwLock::new(HashMap::new()),
            });
        }
        ShardedCache { shards }
    }

    fn get_shard_index(&self, key: &str) -> usize {
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        key.hash(&mut hasher);
        (hasher.finish() as usize) % NUM_SHARDS
    }

    fn get(&self, key: &str) -> Option<V> {
        let idx = self.get_shard_index(key);
        let shard = self.shards[idx].data.read().unwrap();
        shard.get(key).cloned()
    }

    fn insert(&self, key: String, value: V) {
        let idx = self.get_shard_index(&key);
        let mut shard = self.shards[idx].data.write().unwrap();
        shard.insert(key, value);
    }

    fn delete(&self, key: &str) -> Option<V> {
        let idx = self.get_shard_index(key);
        let mut shard = self.shards[idx].data.write().unwrap();
        shard.remove(key)
    }

    fn len(&self) -> usize {
        self.shards
            .iter()
            .map(|s| s.data.read().unwrap().len())
            .sum()
    }

    fn keys(&self) -> Vec<String> {
        let mut all_keys = Vec::new();
        for shard in &self.shards {
            let data = shard.data.read().unwrap();
            for key in data.keys() {
                all_keys.push(key.clone());
            }
        }
        all_keys
    }
}

fn main() {
    let cache = Arc::new(ShardedCache::<i32>::new());

    let start = Instant::now();

    // Параллельная запись из 8 потоков
    let mut handles = Vec::new();

    for t in 0..8 {
        let cache_clone = Arc::clone(&cache);
        let handle = thread::spawn(move || {
            for i in 0..1000 {
                let key = format!("key_{}_{}", t, i);
                cache_clone.insert(key, (t * 1000 + i) as i32);
            }
        });
        handles.push(handle);
    }

    for h in handles {
        h.join().unwrap();
    }

    let write_time = start.elapsed();
    println!("wrote {} entries in {:?}", cache.len(), write_time);

    // Параллельное чтение
    let start = Instant::now();
    let mut read_handles = Vec::new();

    for t in 0..8 {
        let cache_clone = Arc::clone(&cache);
        let handle = thread::spawn(move || {
            let mut found = 0;
            for i in 0..1000 {
                let key = format!("key_{}_{}", t, i);
                if cache_clone.get(&key).is_some() {
                    found += 1;
                }
            }
            found
        });
        read_handles.push(handle);
    }

    let mut total_found = 0;
    for h in read_handles {
        total_found += h.join().unwrap();
    }

    println!("read {} entries in {:?}", total_found, start.elapsed());
    println!("total keys: {}", cache.keys().len());

    // Delete
    cache.delete("key_0_0");
    println!("after delete: {} entries", cache.len());

    let _ = Duration::from_secs(0);
}

