package main

import "fmt"

// Задание 15: Односвязный список

type Node struct {
	Value int
	Next  *Node
}

type LinkedList struct {
	Head *Node
	Size int
}

func (l *LinkedList) PushFront(val int) {
	node := &Node{Value: val, Next: l.Head}
	l.Head = node
	l.Size++
}

func (l *LinkedList) PushBack(val int) {
	node := &Node{Value: val}
	if l.Head == nil {
		l.Head = node
		l.Size++
		return
	}
	current := l.Head
	for current.Next != nil {
		current = current.Next
	}
	current.Next = node
	l.Size++
}

func (l *LinkedList) PopFront() (int, bool) {
	if l.Head == nil {
		return 0, false
	}
	val := l.Head.Value
	l.Head = l.Head.Next
	l.Size--
	return val, true
}

func (l *LinkedList) Find(val int) bool {
	current := l.Head
	for current != nil {
		if current.Value == val {
			return true
		}
		current = current.Next
	}
	return false
}

func (l *LinkedList) Print() {
	current := l.Head
	for current != nil {
		fmt.Printf("%d -> ", current.Value)
		current = current.Next
	}
	fmt.Println("nil")
}

func main() {
	list := &LinkedList{}

	list.PushBack(1)
	list.PushBack(2)
	list.PushBack(3)
	list.PushFront(0)

	list.Print() // 0 -> 1 -> 2 -> 3 -> nil

	fmt.Println("Size:", list.Size)
	fmt.Println("Find 2:", list.Find(2))

	val, _ := list.PopFront()
	fmt.Println("Popped:", val) // 0
	list.Print()                // 1 -> 2 -> 3 -> nil
}

