# Задание 12: Паттерны проектирования — Singleton, Observer, Strategy, Chain of Responsibility

from __future__ import annotations
from abc import ABC, abstractmethod
from typing import Any, Callable

# ========== Singleton через __new__ ==========

class Singleton:
    _instance: Singleton | None = None

    def __new__(cls, *args, **kwargs):
        if cls._instance is None:
            cls._instance = super().__new__( cls)
        return cls._instance

    def __init__(self, value: str = "default"):
        self.value = value

# ========== Singleton через декоратор ==========

def singleton(cls: type) -> Callable:
    instances: dict = {}

    def get_instance(*args, **kwargs):
        if cls not in instances:
            instances[cls] = cls(*args, **kwargs)
        return instances[cls]

    return get_instance

@singleton
class Config:
    def __init__(self):
        self.settings: dict[str, Any] = {}

    def set(self, key: str, value: Any):
        self.settings[key] = value

    def get(self, key: str, default: Any = None) -> Any:
        return self.settings.get(key, default)

# ========== Chain of Responsibility ==========

class Handler(ABC):
    def __init__(self):
        self._next: Handler | None = None

    def set_next(self, handler: Handler) -> Handler:
        self._next = handler
        return handler  # для цепочки: h1.set_next(h2).set_next(h3)

    @abstractmethod
    def handle(self, request: dict) -> str | None:
        ...

    def pass_next(self, request: dict) -> str | None:
        if self._next is not None:
            return self._next.handle(request)
        return None

class AuthHandler(Handler):
    def handle(self, request: dict) -> str | None:
        token = request.get("token")
        if not token:
            return "ERROR: no auth token"
        if token != "valid-token":
            return "ERROR: invalid token"
        print("  [auth] ✓ token valid")
        return self.pass_next(request)

class RateLimitHandler(Handler):
    def __init__(self):
        super().__init__()
        self._count = 0
        self._max = 3

    def handle(self, request: dict) -> str | None:
        self._count += 1
        if self._count > self._max:
            return "ERROR: rate limit exceeded"
        print(f"  [rate] ✓ {self._count}/{self._max}")
        return self.pass_next(request)

class LogHandler(Handler):
    def handle(self, request: dict) -> str | None:
        method = request.get("method", "???")
        path = request.get("path", "???")
        print(f"  [log] {method} {path}")
        return self.pass_next(request)

class BusinessHandler(Handler):
    def handle(self, request: dict) -> str | None:
        return f"OK: processed {request.get('path', '/')}"

# ========== Strategy через callable ==========

class Processor:
    def __init__(self, strategy: Callable[[str], str]):
        self._strategy = strategy

    def set_strategy(self, strategy: Callable[[str], str]):
        self._strategy = strategy

    def process(self, data: str) -> str:
        return self._strategy(data)

def uppercase_strategy(data: str) -> str:
    return data.upper()

def reverse_strategy(data: str) -> str:
    return data[::-1]

def censor_strategy(data: str) -> str:
    bad_words = ["bad", "evil"]
    result = data
    for word in bad_words:
        result = result.replace(word, "***")
    return result

if __name__ == "__main__":
    # Singleton
    print("=== Singleton ===")
    s1 = Singleton("first")
    s2 = Singleton("second")
    print(f"s1 is s2: {s1 is s2}")
    print(f"s1.value: {s1.value}")  # "second" — __init__ вызывается дважды!
    print()

    # Singleton через декоратор
    print("=== Config Singleton ===")
    c1 = Config()
    c1.set("debug", True)
    c2 = Config()
    print(f"c1 is c2: {c1 is c2}")
    print(f"c2.get('debug'): {c2.get('debug')}")
    print()

    # Chain of Responsibility
    print("=== Chain of Responsibility ===")
    auth = AuthHandler()
    rate = RateLimitHandler()
    log = LogHandler()
    biz = BusinessHandler()

    auth.set_next(rate).set_next(log).set_next(biz)

    requests = [
        {"method": "GET", "path": "/api/data", "token": "valid-token"},
        {"method": "POST", "path": "/api/submit", "token": "valid-token"},
        {"method": "GET", "path": "/api/data"},  # нет токена
        {"method": "GET", "path": "/api/data", "token": "valid-token"},  # 3-й
        {"method": "GET", "path": "/api/data", "token": "valid-token"},  # 4-й — rate limit
    ]

    for i, req in enumerate(requests, 1):
        print(f"\nRequest {i}:")
        result = auth.handle(req)
        print(f"  → {result}")
    print()

    # Strategy
    print("=== Strategy ===")
    proc = Processor(uppercase_strategy)

    print(proc.process("hello world"))

    proc.set_strategy(reverse_strategy)
    print(proc.process("hello world"))

    proc.set_strategy( censor_strategy)
    print(proc.process("this is bad and evil stuff"))

