package main

import (
	"fmt"
	"math"
)

// Задание 18: Интерфейсы и полиморфизм

type Shape interface {
	Area() float64
	Perimeter() float64
	Name() string
}

type Rectangle struct {
	Width  float64
	Height float64
}

func (r Rectangle) Area() float64 {
	return r.Width * r.Height
}

func (r Rectangle) Perimeter() float64 {
	return 2 * (r.Width + r.Height)
}

func (r Rectangle) Name() string {
	return "Rectangle"
}

type Circle struct {
	Radius float64
}

func (c Circle) Area() float64 {
	return math.Pi * c.Radius * c.Radius
}

func (c Circle) Perimeter() float64 {
	return 2 * math.Pi * c.Radius
}

func (c Circle) Name() string {
	return "Circle"
}

type Triangle struct {
	A, B, C float64 // стороны
}

func (t Triangle) Area() float64 {
	s := t.Perimeter() / 2
	return math.Sqrt(s * (s - t.A) * (s - t.B) * (s - t.C))
}

func (t Triangle) Perimeter() float64 {
	return t.A + t.B + t.C
}

func (t Triangle) Name() string {
	return "Triangle"
}

func NewShape(kind string, params ...float64) (Shape, error) {
	switch kind {
	case "rectangle":
		if len(params) != 2 {
			return nil, fmt.Errorf("rectangle needs 2 params")
		}
		return Rectangle{Width: params[0], Height: params[1]}, nil
	case "circle":
		if len(params) != 1 {
			return nil, fmt.Errorf("circle needs 1 param")
		}
		return Circle{Radius: params[0]}, nil
	case "triangle":
		if len(params) != 3 {
			return nil, fmt.Errorf("triangle needs 3 params")
		}
		return Triangle{A: params[0], B: params[1], C: params[2]}, nil
	default:
		return nil, fmt.Errorf("unknown shape: %s", kind)
	}
}

func PrintInfo(s Shape) {
	fmt.Printf("%s: area=%.2f perimeter=%.2f\n", s.Name(), s.Area(), s.Perimeter())
}

func main() {
	shapes := []Shape{
		Rectangle{Width: 10, Height: 5},
		Circle{Radius: 7},
		Triangle{A: 3, B: 4, C: 5},
	}

	for _, s := range shapes {
		PrintInfo(s)
	}

	fmt.Println("\n--- Factory ---")
	sh, err := NewShape("circle", 3.0)
	if err != nil {
		fmt.Println("Error:", err)
	} else {
		PrintInfo(sh)
	}
}

package main

import "fmt"

// Задание 27: Встраивание (embedding) — "наследование" в Go
//
// В Go нет классов и наследования. Вместо этого — встраивание структур.
// Встроенная структура "продвигает" свои поля и методы наверх.

// Базовая "сущность"
type Entity struct {
	ID   int
	Name string
}

func (e Entity) String() string {
	return fmt.Sprintf("[%d] %s", e.ID, e.Name)
}

// User "наследует" Entity через встраивание
type User struct {
	Entity // встраиваем Entity (без имени поля — это embedding)
	Email  string
	Role   string
}

// Переопределяем String() — "override"
func (u User) String() string {
	return fmt.Sprintf("%s <%s> role=%s", u.Entity.String(), u.Email, u.Role)
}

// Admin "наследует" User
type Admin struct {
	User        // встраиваем User
	Permissions []string
}

func (a Admin) HasPermission(perm string) bool {
	for _, p := range a.Permissions {
		if p == perm {
			return true
		}
	}
	return false
}

// Переопределяем String() ещё раз
func (a Admin) String() string {
	return fmt.Sprintf("ADMIN: %s perms=%v", a.User.String(), a.Permissions)
}

func main() {
	user := User{
		Entity: Entity{ID: 1, Name: "Alice"},
		Email:  "alice@example.com",
		Role:   "editor",
	}

	admin := Admin{
		User: User{
			Entity: Entity{ID: 2, Name: "Bob"},
			Email:  "bob@example.com",
			Role:   "admin",
		},
		Permissions: []string{"read", "write", "delete"},
	}

	// Доступ к полям Entity прямо через Admin (продвижение полей)
	fmt.Println(admin.ID)    // 2 — поле Entity.ID доступно напрямую
	fmt.Println(admin.Name)  // Bob — поле Entity.Name доступно напрямую
	fmt.Println(admin.Email) // bob@example.com — поле User.Email

	fmt.Println(user)                         // вызовет User.String()
	fmt.Println(admin)                        // вызовет Admin.String()
	fmt.Println(admin.HasPermission("write")) // true
	fmt.Println(admin.HasPermission("sudo"))  // false
}

package main

import (
	"fmt"
	"math"
)

// Задание 28: Интерфейсы и полиморфизм
//
// Интерфейс в Go — набор методов. Любой тип, у которого есть эти методы,
// автоматически реализует интерфейс (неявная реализация, duck typing).

type Shape interface {
	Area() float64
	Perimeter() float64
	String() string
}

// Circle реализует Shape
type Circle struct {
	Radius float64
}

func (c Circle) Area() float64 {
	return math.Pi * c.Radius * c.Radius
}

func (c Circle) Perimeter() float64 {
	return 2 * math.Pi * c.Radius
}

func (c Circle) String() string {
	return fmt.Sprintf("Circle(r=%.1f)", c.Radius)
}

// Rectangle реализует Shape
type Rectangle struct {
	Width, Height float64
}

func (r Rectangle) Area() float64 {
	return r.Width * r.Height
}

func (r Rectangle) Perimeter() float64 {
	return 2 * (r.Width + r.Height)
}

func (r Rectangle) String() string {
	return fmt.Sprintf("Rect(%.1fx%.1f)", r.Width, r.Height)
}

// Triangle реализует Shape
type Triangle struct {
	A, B, C float64 // стороны
}

func (t Triangle) Perimeter() float64 {
	return t.A + t.B + t.C
}

func (t Triangle) Area() float64 {
	// формула Герона
	s := t.Perimeter() / 2
	return math.Sqrt(s * (s - t.A) * (s - t.B) * (s - t.C))
}

func (t Triangle) String() string {
	return fmt.Sprintf("Triangle(%.1f,%.1f,%.1f)", t.A, t.B, t.C)
}

// Полиморфная функция — принимает любой Shape
func printShapeInfo(s Shape) {
	fmt.Printf("%-25s area=%.2f  perim=%.2f\n", s, s.Area(), s.Perimeter())
}

// Сумма площадей — слайс интерфейсов
func totalArea(shapes []Shape) float64 {
	total := 0.0
	for _, s := range shapes {
		total += s.Area()
	}
	return total
}

func main() {
	shapes := []Shape{
		Circle{Radius: 5},
		Rectangle{Width: 3, Height: 4},
		Triangle{A: 3, B: 4, C: 5},
	}

	for _, s := range shapes {
		printShapeInfo(s)
	}

	fmt.Printf("\nTotal area: %.2f\n", totalArea(shapes))

	// Type assertion — проверка конкретного типа
	var s Shape = Circle{Radius: 10}

	if circle, ok := s.(Circle); ok {
		fmt.Printf("It's a circle with radius %.1f\n", circle.Radius)
	}

	// Type switch
	switch v := s.(type) {
	case Circle:
		fmt.Println("circle:", v.Radius)
	case Rectangle:
		fmt.Println("rect:", v.Width)
	case Triangle:
		fmt.Println("triangle:", v.A)
	}
}

package main

import (
	"fmt"
	"sort"
	"strings"
)

// Задание 29: Паттерн Стратегия через интерфейсы
//
// Стратегия — поведение передаётся как интерфейс.
// Можно менять алгоритм на лету без изменения основного кода.

// Интерфейс стратегии сортировки
type SortStrategy interface {
	Sort(items []string)
	Name() string
}

// Стратегия 1: по алфавиту
type AlphaSort struct{}

func (a AlphaSort) Sort(items []string) {
	sort.Strings(items)
}

func (a AlphaSort) Name() string {
	return "alphabetical"
}

// Стратегия 2: по длине строки
type LengthSort struct{}

func (l LengthSort) Sort(items []string) {
	sort.Slice(items, func(i, j int) bool {
		return len(items[i]) < len(items[j])
	})
}

func (l LengthSort) Name() string {
	return "by length"
}

// Стратегия 3: по алфавиту в обратном порядке
type ReversSort struct{}

func (r ReversSort) Sort(items []string) {
	sort.Slice(items, func(i, j int) bool {
		return items[i] > items[j]
	})
}

func (r ReversSort) Name() string {
	return "reverse alphabetical"
}

// Контекст — использует стратегию
type Sorter struct {
	strategy SortStrategy
	items    []string
}

func NewSorter(strategy SortStrategy) *Sorter {
	return &Sorter{strategy: strategy}
}

func (s *Sorter) SetStrategy(strategy SortStrategy) {
	s.strategy = strategy
}

func (s *Sorter) AddItems(items ...string) {
	s.items = append(s.items, items...)
}

func (s *Sorter) Sort() {
	s.strategy.Sort(s.items)
}

func (s *Sorter) Print() {
	fmt.Printf("[%s]: %s\n", s.strategy.Name(), strings.Join(s.items, ", "))
}

// --- Ещё пример: стратегия фильтрации ---

type FilterStrategy interface {
	Filter(items []string) []string
}

// Фильтр: только строки длиннее N
type MinLengthFilter struct {
	MinLen int
}

func (f MinLengthFilter) Filter(items []string) []string {
	// вернуть только те items, у которых len >= f.MinLen
	result := make([]string, 0, len(items))
	for _, item := range items {
		if len(item) >= f.MinLen {
			result = append(result, item)
		}
	}
	return result
}

// Фильтр: только строки содержащие подстроку
type ContainsFilter struct {
	Substr string
}

func (f ContainsFilter) Filter(items []string) []string {
	// вернуть только те items, которые содержат f.Substr
	result := make([]string, 0, len(items))
	for _, item := range items {
		if strings.Contains(item, f.Substr) {
			result = append(result, item)
		}
	}
	return result
}

func applyFilter(items []string, f FilterStrategy) []string {
	return f.Filter(items)
}

func main() {
	sorter := NewSorter(AlphaSort{})
	sorter.AddItems("banana", "apple", "cherry", "date", "elderberry")

	sorter.Sort()
	sorter.Print() // [alphabetical]: apple, banana, cherry, date, elderberry

	sorter.SetStrategy(LengthSort{})
	sorter.Sort()
	sorter.Print() // [by length]: date, apple, banana, cherry, elderberry

	sorter.SetStrategy(ReversSort{})
	sorter.Sort()
	sorter.Print() // [reverse alphabetical]: elderberry, date, cherry, banana, apple

	// Фильтрация
	words := []string{"go", "rust", "python", "c", "javascript", "ruby"}

	long := applyFilter(words, MinLengthFilter{MinLen: 4})
	fmt.Println("long:", long) // [rust, python, javascript, ruby]

	withR := applyFilter(words, ContainsFilter{"r"})
	fmt.Println("with r:", withR) // [rust, ruby]
}

package main

import (
	"fmt"
	"strings"
	"time"
)

// Задание 30: Паттерн Декоратор через встраивание интерфейса
//
// Декоратор оборачивает объект, добавляя поведение без изменения исходного кода.
// В Go — через встраивание интерфейса в структуру.

// Базовый интерфейс
type Logger interface {
	Log(msg string)
}

// Простой логгер
type SimpleLogger struct{}

func (l SimpleLogger) Log(msg string) {
	fmt.Println(msg)
}

// Декоратор 1: добавляет временную метку
type TimestampLogger struct {
	Logger // встраиваем интерфейс Logger — это ключ к паттерну
}

func (t TimestampLogger) Log(msg string) {
	stamped := fmt.Sprintf("[%s] %s", time.Now().Format("15:04:05"), msg)
	t.Logger.Log(stamped) // вызываем Log встроенного логгера
}

// Декоратор 2: добавляет уровень (INFO, ERROR...)
type LevelLogger struct {
	Logger // встраиваем Logger
	Level  string
}

func (l LevelLogger) Log(msg string) {
	leveled := fmt.Sprintf("%s: %s", l.Level, msg)
	l.Logger.Log(leveled) // передаём дальше по цепочке
}

// Декоратор 3: преобразует в uppercase
type UpperLogger struct {
	Logger
}

func (u UpperLogger) Log(msg string) {
	u.Logger.Log(strings.ToUpper(msg))
}

// Декоратор 4: фильтрует сообщения по подстроке
type FilterLogger struct {
	Logger
	MustContain string
}

func (f FilterLogger) Log(msg string) {
	if strings.Contains(msg, f.MustContain) {
		f.Logger.Log(msg)
	}
	// иначе — сообщение проглатывается
}

func main() {
	// Простой логгер
	var logger Logger = SimpleLogger{}
	logger.Log("hello")
	// hello

	// Оборачиваем в timestamp
	logger = TimestampLogger{Logger: logger}
	logger.Log("with time")
	// [15:04:05] with time

	// Оборачиваем ещё в level
	logger = LevelLogger{Logger: logger, Level: "INFO"}
	logger.Log("server started")
	// INFO: [15:04:05] server started

	// Цепочка: Simple → Timestamp → Upper → Level
	chain := LevelLogger{
		Logger: UpperLogger{
			Logger: TimestampLogger{
				Logger: SimpleLogger{},
			},
		},
		Level: "ERROR",
	}
	chain.Log("something broke")
	// ERROR: [15:04:05] SOMETHING BROKE

	// С фильтром: только сообщения содержащие "FAIL"
	filtered := FilterLogger{
		Logger:      SimpleLogger{},
		MustContain: "FAIL",
	}
	filtered.Log("all good")        // ← не напечатается
	filtered.Log("FAIL: disk full") // FAIL: disk full
}

package main

import "fmt"

// Задание 31: Паттерн Наблюдатель (Observer)
//
// Наблюдатель — подписчики получают уведомления при изменении состояния.

// Интерфейс наблюдателя
type Observer interface {
	OnEvent(event string, data any) // any = interface{}
}

// Интерфейс издателя
type Publisher interface {
	Subscribe(observer Observer)
	Unsubscribe(observer Observer)
	Notify(event string, data any)
}

// --- Конкретный издатель: Магазин ---

type Store struct {
	name      string
	observers []Observer
	products  map[string]float64
}

func NewStore(name string) *Store {
	return &Store{
		name:      name,
		observers: make([]Observer, 0),
		products:  make(map[string]float64),
	}
}

func (s *Store) Subscribe(obs Observer) {
	s.observers = append(s.observers, obs)
}

func (s *Store) Unsubscribe(obs Observer) {
	// найти obs в s.observers и удалить.
	// Сравнивать через == (интерфейсы сравнимы если underlying type сравним)
	for i, o := range s.observers {
		if o == obs {
			s.observers = append(s.observers[:i], s.observers[i+1:]...)
			return
		}
	}
}

func (s *Store) Notify(event string, data any) {
	for _, obs := range s.observers {
		obs.OnEvent(event, data)
	}
}

func (s *Store) AddProduct(name string, price float64) {
	s.products[name] = price
	s.Notify("product_added", map[string]any{
		"product": name,
		"price":   price,
	})
}

func (s *Store) UpdatePrice(name string, newPrice float64) {
	oldPrice := s.products[name]
	s.products[name] = newPrice
	s.Notify("price_changed", map[string]any{
		"product":   name,
		"old_price": oldPrice,
		"new_price": newPrice,
	})
}

// --- Конкретные наблюдатели ---

type EmailNotifier struct {
	Address string
}

func (e EmailNotifier) OnEvent(event string, data any) {
	fmt.Printf("[EMAIL → %s] event=%s data=%v\n", e.Address, event, data)
}

type DashboardWidget struct {
	Name string
}

func (d DashboardWidget) OnEvent(event string, data any) {
	fmt.Printf("[DASHBOARD:%s] %s: %v\n", d.Name, event, data)
}

type PriceWatcher struct {
	ProductName string
	MaxPrice    float64
}

func (p PriceWatcher) OnEvent(event string, data any) {
	if event != "price_changed" {
		return
	}
	// если data — это map[string]any и product совпадает с p.ProductName
	// и new_price (float64) > p.MaxPrice — напечатать предупреждение
	m, ok := data.(map[string]any)
	if !ok {
		return
	}
	product, _ := m["product"].(string)
	newPrice, _ := m["new_price"].(float64)
	if product == p.ProductName && newPrice > p.MaxPrice {
		fmt.Printf("⚠ PRICE ALERT: %s is now %v (max: %v)\n", product, newPrice, p.MaxPrice)
	}
}

func main() {
	store := NewStore("TechShop")

	email := EmailNotifier{Address: "user@mail.com"}
	dash := DashboardWidget{Name: "main"}
	watcher := PriceWatcher{ProductName: "laptop", MaxPrice: 1000}

	store.Subscribe(email)
	store.Subscribe(dash)
	store.Subscribe(watcher)

	store.AddProduct("laptop", 900)
	fmt.Println("---")
	store.UpdatePrice("laptop", 1200) // watcher должен среагировать
	fmt.Println("---")

	// Отписываем email
	store.Unsubscribe(email)
	store.AddProduct("mouse", 25) // email не получит
}

package main

import (
	"fmt"
	"time"
)

// Задание 32: Functional Options + Factory
//
// Functional Options — идиоматичный Go-паттерн для конфигурации.
// Вместо длинного конструктора или builder — передаём функции-опции.

type Server struct {
	host         string
	port         int
	readTimeout  time.Duration
	writeTimeout time.Duration
	maxConns     int
	tls          bool
}

// Option — тип функции, которая модифицирует Server
type Option func(s *Server)

func WithPort(port int) Option {
	return func(s *Server) {
		s.port = port
	}
}

func WithTimeouts(read, write time.Duration) Option {
	return func(s *Server) {
		s.readTimeout = read
		s.writeTimeout = write
	}
}

func WithMaxConns(n int) Option {
	return func(s *Server) {
		s.maxConns = n
	}
}

func WithTLS(enabled bool) Option {
	return func(s *Server) {
		s.tls = enabled
	}
}

// Конструктор с опциями
func NewServer(host string, opts ...Option) *Server {
	// Дефолтные значения
	s := &Server{
		host:         host,
		port:         8080,
		readTimeout:  5 * time.Second,
		writeTimeout: 10 * time.Second,
		maxConns:     100,
		tls:          false,
	}

	// Применяем опции
	for _, opt := range opts {
		opt(s)
	}

	return s
}

func (s *Server) String() string {
	proto := "http"
	if s.tls {
		proto = "https"
	}
	return fmt.Sprintf("%s://%s:%d (read=%v write=%v maxConns=%d)",
		proto, s.host, s.port, s.readTimeout, s.writeTimeout, s.maxConns)
}

// --- Ещё пример: интерфейс + фабрика ---

type Storage interface {
	Save(key string, value []byte) error
	Load(key string) ([]byte, error)
	Name() string // метод Name
}

type MemoryStorage struct {
	data map[string][]byte
}

func (m *MemoryStorage) Save(key string, value []byte) error {
	m.data[key] = value
	return nil
}

func (m *MemoryStorage) Load(key string) ([]byte, error) {
	v, ok := m.data[key]
	if !ok {
		return nil, fmt.Errorf("key %s not found", key)
	}
	return v, nil
}

func (m *MemoryStorage) Name() string {
	return "memory"
}

type DiskStorage struct {
	BasePath string
}

func (d *DiskStorage) Save(key string, value []byte) error {
	fmt.Printf("[disk] saving %s to %s/%s\n", key, d.BasePath, key)
	return nil // упрощённо
}

func (d *DiskStorage) Load(key string) ([]byte, error) {
	fmt.Printf("[disk] loading %s from %s/%s\n", key, d.BasePath, key)
	return []byte("fake data"), nil
}

func (d *DiskStorage) Name() string {
	return "disk"
}

// Фабрика — создаёт Storage по имени
func NewStorage(kind string) (Storage, error) {
	switch kind {
	case "memory":
		return &MemoryStorage{data: make(map[string][]byte)}, nil
	case "disk":
		return &DiskStorage{BasePath: "/tmp/data"}, nil
	default:
		return nil, fmt.Errorf("unknown storage: %s", kind)
	}
}

func main() {
	// Functional Options
	s1 := NewServer("localhost")
	fmt.Println(s1)

	s2 := NewServer("api.example.com",
		WithPort(443),
		WithTLS(true),
		WithMaxConns(1000),
		WithTimeouts(30*time.Second, 60*time.Second),
	)
	fmt.Println(s2)

	// Factory
	for _, kind := range []string{"memory", "disk", "redis"} {
		storage, err := NewStorage(kind)
		if err != nil {
			fmt.Printf("error: %v\n", err)
			continue
		}
		fmt.Printf("created %s storage\n", storage.Name())
	}
}

package main

import (
	"fmt"
	"sync"
	"time"
)

// Задание 14: Rate Limiter через ticker
//
// ========== ПОЯСНЕНИЕ ==========
//
// Rate Limiter — ограничитель частоты запросов (token bucket algorithm).
//
// ЗАЧЕМ:
//   Защищает сервис от перегрузки. Например: API позволяет 5 запросов/сек —
//   Rate Limiter гарантирует, что клиент не превысит лимит.
//
// КАК РАБОТАЕТ (Token Bucket):
//   1. Есть «ведро» (буферизированный канал) с токенами
//   2. Каждый запрос забирает 1 токен из ведра (блокируется если пусто)
//   3. Ticker периодически добавляет новые токены с заданной частотой
//   4. burst — максимальный размер ведра (сколько запросов можно сделать разом)
//
// КЛЮЧЕВЫЕ КОНЦЕПЦИИ:
//   - time.Ticker — генерирует события через равные интервалы (rate)
//   - chan struct{} — канал-семафор, struct{} занимает 0 байт (идиоматично для сигналов)
//   - Буферизированный канал как ведро: ёмкость = burst
//   - select с default — неблокирующая запись (если ведро полно — токен теряется)
//   - close(chan) — сигнал остановки горутины пополнения
//
// ПАТТЕРН:
//   NewRateLimiter(rate=5, burst=2):
//     - Ticker тикает каждые 200ms (1s / 5)
//     - Ведро вмещает 2 токена (burst)
//     - Сначала ведро заполняется burst токенами → первые 2 запроса проходят сразу
//     - Далее каждые 200ms добавляется 1 токен → запросы идут с частотой 5/сек
//
// ================================

type RateLimiter struct {
	ticker *time.Ticker
	tokens chan struct{}
	stop   chan int
}

func NewRateLimiter(rate int, burst int) *RateLimiter {
	rl := &RateLimiter{
		ticker: time.NewTicker(time.Second / time.Duration(rate)), // интервал = 1s/rate
		tokens: make(chan struct{}, burst),                        // ёмкость ведра = burst
		stop:   make(chan int),                                    // сигнал остановки
	}

	// Заполняем начальные токены (burst штук — для мгновенного старта)
	for i := 0; i < burst; i++ {
		rl.tokens <- struct{}{}
	}

	// Горутина пополнения — добавляет токен каждый тик
	go func() {
		for {
			select {
			case <-rl.stop: // получили сигнал остановки
				rl.ticker.Stop() // останавливаем ticker, освобождаем ресурсы
				return
			case <-rl.ticker.C: // очередной тик — пора добавить токен
				select {
				case rl.tokens <- struct{}{}: // кладём токен в ведро
				default:
				}
			}
		}
	}()

	return rl
}

func (rl *RateLimiter) Wait() {
	<-rl.tokens // блокируемся пока не получим токен из ведра
}

func (rl *RateLimiter) Close() {
	close(rl.stop) // close отправляет сигнал всем читателям канала
}

func main() {
	limiter := NewRateLimiter(5, 2) // 5 req/sec, burst 2
	defer limiter.Close()

	var wg sync.WaitGroup
	start := time.Now()

	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			limiter.Wait() // ждём разрешения от rate limiter
			fmt.Printf("request %d at %v\n", id, time.Since(start))
		}(i)
	}

	wg.Wait()
	fmt.Println("All requests done")
}

