# Задание 2: Генераторы и итераторы

from typing import Generator, Iterator

# --- Генератор 1: бесконечная последовательность Фибоначчи ---

def fibonacci() -> Generator[int, None, None]:
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b

# --- Генератор 2: чтение файла чанками ---

def read_chunks(data: str, chunk_size: int) -> Generator[str, None, None]:
    for i in range(0, len(data), chunk_size):
        yield data[i:i + chunk_size]

# --- Генератор 3: pipeline — цепочка генераторов ---

def numbers(n: int) -> Generator[int, None, None]:
    for i in range(n):
        yield i

def even_only(gen: Generator) -> Generator[int, None, None]:
    for val in gen:
        if val % 2 == 0:
            yield val

def squared(gen: Generator) -> Generator[int, None, None]:
    for val in gen:
        yield val * val

# --- Свой итератор через класс ---

class Countdown:
    """Итератор обратного отсчёта: 5, 4, 3, 2, 1"""

    def __init__(self, start: int):
        self.current = start

    def __iter__(self) -> "Countdown":
        return self

    def __next__(self) -> int:
        if self.current <= 0:
            raise StopIteration
        val = self.current
        self.current -= 1
        return val

# --- Генератор 4: flatten вложенных списков (рекурсивный) ---

def flatten(lst: list) -> Generator:
    for item in lst:
        if isinstance(item, list):
            yield from flatten(item)
        else:
            yield item

# --- send() в генератор ---

def accumulator() -> Generator[float, float, None]:
    total = 0.0
    while True:
        value = yield total
        if value is None:
            break
        total += value

if __name__ == "__main__":
    # Фибоначчи — первые 10
    fib = fibonacci()
    for _ in range(10):
        print(next(fib), end=" ")
    print()

    # Чанки
    for chunk in read_chunks("HelloWorld!!!", 4):
        print(chunk)
    print()

    # Pipeline: числа 0..9 → только чётные → в квадрат
    pipe = squared(even_only(numbers(10)))
    print(list(pipe))

    # Countdown
    for val in Countdown(5):
        print(val, end=" ")
    print()

    # Flatten
    nested = [1, [2, [3, 4], 5], [6, 7]]
    print(list(flatten(nested)))

    # Accumulator с send
    acc = accumulator()
    next(acc)          # инициализация генератора
    print(acc.send(10))  # 10.0
    print(acc.send(20))  # 30.0
    print(acc.send(5))   # 35.0

