// Задание 8: Fibonacci через Iterator trait (аналог Go generator с каналом)

struct Fibonacci {
    a: u64,
    b: u64,
}

impl Fibonacci {
    fn new() -> Self {
        Fibonacci { a: 0, b: 1 }
    }
}

impl Iterator for Fibonacci {
    type Item = u64;

    fn next(&mut self) -> Option<Self::Item> {
        let current = self.a;
        let new_b = self.a + self.b;
        self.a = self.b;
        self.b = new_b;
        Some(current)
    }
}

// Обобщённый Range-итератор
struct RangeIter {
    current: i32,
    end: i32,
    step: i32,
}

impl RangeIter {
    fn new(start: i32, end: i32, step: i32) -> Self {
        RangeIter {
            current: start,
            end,
            step,
        }
    }
}

impl Iterator for RangeIter {
    type Item = i32;

    fn next(&mut self) -> Option<i32> {
        if self.current >= self.end {
            return None;
        }
        let val = self.current;
        self.current += self.step;
        Some(val)
    }
}

// Бесконечный итератор натуральных чисел
struct Naturals {
    current: u64,
}

impl Naturals {
    fn new() -> Self {
        Naturals { current: 1 }
    }
}

impl Iterator for Naturals {
    type Item = u64;

    fn next(&mut self) -> Option<u64> {
        let val = self.current;
        self.current += 1;
        Some(val)
    }
}

fn main() {
    // Fibonacci — первые 10
    let fibs: Vec<u64> = Fibonacci::new().take(10).collect();
    println!("first 10 fib: {:?}", fibs);

    // Fibonacci — сумма первых 20
    let sum: u64 = Fibonacci::new().take(20).sum();
    println!("sum of first 20: {}", sum);

    // Fibonacci — первый > 1000
    let big = Fibonacci::new().find(|&x| x > 1000).unwrap();
    println!("first fib > 1000: {}", big);

    // RangeIter
    println!("\nrange 0..20 step 3:");
    let range_vals: Vec<i32> = RangeIter::new(0, 20, 3).collect();
    println!("  {:?}", range_vals);

    // Naturals + адаптеры
    println!("\nfirst 5 squares of odd naturals:");
    let result: Vec<u64> = Naturals::new()
        .filter(|n| n % 2 != 0) // нечётные
        .map(|n| n * n) // квадрат
        .take(5)
        .collect();
    println!("  {:?}", result);

    // zip двух итераторов
    println!("\nfib zipped with index:");
    let zipped: Vec<(i32, u64)> = (0..5).zip(Fibonacci::new()).collect();
    println!("  {:?}", zipped);

    // enumerate
    println!("\nenumerated fibs:");
    for (i, fib) in Fibonacci::new().take(8).enumerate() {
        println!("  fib[{}] = {}", i, fib);
    }
}

