package main

import "fmt"

// Задание 9: Defer, Panic, Recover

func protect(f func()) {
	defer func() {
		if r := recover(); r != nil {
			fmt.Println("Recovered:", r)
		}
	}()
	f()
}

func riskyOperation() {
	fmt.Println("before panic")
	panic("something went wrong!")
	fmt.Println("after panic") // не выполнится
}

func deferOrder() {
	fmt.Println("start")
	defer fmt.Println("first defer")
	defer fmt.Println("second defer")
	defer fmt.Println("third defer")
	fmt.Println("end")
	// Вывод: start, end, third defer, second defer, first defer
}

func deferWithArgs() (result int) {
	x := 10
	defer func() {
		result = result + x
	}()
	return x * 2
	// Вернёт 30 (20 + 10)
}

func main() {
	fmt.Println("--- deferOrder ---")
	deferOrder()

	fmt.Println("\n--- protect ---")
	protect(riskyOperation)
	fmt.Println("After protect — program continues")

	fmt.Println("\n--- deferWithArgs ---")
	fmt.Println("Result:", deferWithArgs())
}

