from __future__ import annotations
import traceback
from typing import Any, Callable

# --- Кастомные исключения с иерархией ---

class AppError(Exception):
    """Базовая ошибка приложения"""
    def __init__(self, message: str, code: int = 0):
        super().__init__(message)
        self.code = code

class ValidationError(AppError):
    """Ошибка валидации"""
    def __init__(self, field: str, message: str):
        super().__init__(f"{field}: {message}", code=400)
        self.field = field

class NotFoundError(AppError):
    def __init__(self, entity: str, id: Any):
        AppError.__init__(self, f"{entity} with id={id} not found", code=404)
        self.entity = entity
        self.id = id

class AuthError(AppError):
    def __init__(self, reason: str):
        super().__init__( f"auth failed: {reason}", code=401)

# --- Цепочка исключений (exception chaining) ---

def fetch_user(user_id: int) -> dict:
    if user_id <= 0:
        raise ValidationError("user_id", "must be positive")
    if user_id > 100:
        raise NotFoundError("User", user_id)
    return {"id": user_id, "name": "Alice"}

def get_user_profile(user_id: int) -> dict:
    try:
        user = fetch_user(user_id)
        return {"profile": user["name"]}
    except AppError as e:
        # Цепочка: оригинальная ошибка сохраняется в __cause__
        raise RuntimeError(f"failed to get profile for user {user_id}") from e

# --- ExceptionGroup (Python 3.11+) ---

def validate_form(data: dict) -> None:
    errors: list[ValidationError] = []

    if not data.get("name"):
        errors.append(ValidationError("name", "is required"))
    if not data.get("email") or "@" not in data.get("email", ""):
        errors.append(ValidationError("email", "invalid format"))
    if data.get("age", 0) < 0:
        errors.append(ValidationError("age", "must be non-negative"))

    if errors:
        raise ExceptionGroup(  "validation failed", errors)

# --- Retry с обработкой ---

def retry_on(
    *exceptions: type[Exception],
    max_attempts: int = 3,
) -> Callable:
    """Декоратор: ретраит только указанные типы исключений"""

    def decorator(func: Callable) -> Callable:
        def wrapper(*args, **kwargs):
            last_err: Exception | None = None
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_err = e
                    print(f"  attempt {attempt} failed: {e}")
                # Другие исключения пролетают насквозь
            raise last_err
        return wrapper
    return decorator

# --- Result-тип (вместо исключений) ---

class Result:
    def __init__(self, value: Any = None, error: Exception | None = None):
        self._value = value
        self._error = error

    @property
    def is_ok(self) -> bool:
        return self._error is None

    @property
    def value(self) -> Any:
        if not self.is_ok:
            raise RuntimeError(f"Result is error: {self._error}")
        return self._value

    @property
    def error(self) -> Exception | None:
        return self._error

    @classmethod
    def ok(cls, value: Any) -> "Result":
        return cls(value=value)

    @classmethod
    def err(cls, error: Exception) -> "Result":
        return cls(error=error)

    def map(self, func: Callable) -> "Result":
        if not self.is_ok:
            return self
        try:
            return Result.ok(func(self._value))
        except Exception as e:
            return Result.err(e)

def safe_divide(a: float, b: float) -> Result:
    if b == 0:
        return Result.err(ZeroDivisionError("division by zero"))
    return Result.ok(a / b)

if __name__ == "__main__":
    # Кастомные исключения
    print("=== Custom Exceptions ===")
    for uid in [5, -1, 999]:
        try:
            print(f"user {uid}:", fetch_user(uid))
        except ValidationError as e:
            print(f"  validation: {e} (field={e.field})")
        except NotFoundError as e:
            print(f"  not found: {e} (entity={e.entity})")
    print()

    # Цепочка
    print("=== Exception Chaining ===")
    try:
        get_user_profile(-1)
    except RuntimeError as e:
        print(f"  error: {e}")
        print(f"  cause: {e.__cause__}")
    print()

    # ExceptionGroup
    print("=== ExceptionGroup ===")
    try:
        validate_form({"name": "", "email": "bad", "age": -5})
    except* ValidationError as eg:
        for err in eg.exceptions:
            print(f"  {err.field}: {err}")
    print()

    # Retry
    print("=== Retry ===")
    counter = 0

    @retry_on(ConnectionError, max_attempts=4)
    def flaky_connect():
        global counter
        counter += 1
        if counter < 3:
            raise ConnectionError("refused")
        return "connected"

    print(f"  result: {flaky_connect()}")
    print()

    # Result
    print("=== Result type ===")
    r1 = safe_divide(10, 3)
    r2 = safe_divide(10, 0)

    print(f"10/3 ok={r1.is_ok}, value={r1.value:.2f}")
    print(f"10/0 ok={r2.is_ok}, error={r2.error}")

    # map chain
    result = safe_divide(100, 4).map(lambda x: x * 2).map(int)
    print(f"100/4 * 2 = {result.value}")

