// Задание 9: Обработка ошибок (аналог defer/panic/recover и error wrapping в Go)

use std::fmt;
use std::num::ParseIntError;

// --- Кастомные ошибки с иерархией ---

#[derive(Debug)]
enum AppError {
    NotFound { entity: String, id: i64 },
    Validation(String),
    Parse(ParseIntError), // оборачиваем стандартную ошибку
    Internal(String),
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AppError::NotFound { entity, id } => {
                write!(f, "{} with id={} not found", entity, id)
            }
            AppError::Validation(msg) => write!(f, "validation: {}", msg),
            AppError::Parse(err) => write!(f, "parse error: {}", err),
            AppError::Internal(msg) => write!(f, "internal: {}", msg),
        }
    }
}

// Автоконверсия ParseIntError → AppError
impl From<ParseIntError> for AppError {
    fn from(err: ParseIntError) -> Self {
        AppError::Parse(err)
    }
}

// --- Функции с Result + ? ---

fn parse_id(input: &str) -> Result<u64, AppError> {
    let id: u64 = input.parse()?; // оператор ? — пробрасывает ошибку
    if id == 0 {
        return Err(AppError::Validation("id cannot be zero".into()));
    }
    Ok(id)
}

fn find_user(id: u64) -> Result<String, AppError> {
    match id {
        1 => Ok("Alice".to_string()),
        2 => Ok("Bob".to_string()),
        _ => Err(AppError::NotFound {
            entity: "User".to_string(),
            id: id as i64,
        }),
    }
}

fn get_user_name(input: &str) -> Result<String, AppError> {
    let id = parse_id(input)?; // ? пробрасывает ошибку наверх
    let name = find_user(id)?;
    Ok(format!("User: {}", name))
}

// --- panic + catch_unwind (аналог panic/recover в Go) ---

fn risky_function(x: i32) -> i32 {
    if x < 0 {
        panic!("negative value: {}", x);
    }
    x * 2
}

fn safe_call(x: i32) -> Result<i32, String> {
    let result = std::panic::catch_unwind(|| risky_function(x));

    match result {
        Ok(val) => Ok(val),
        Err(_) => Err(format!("panic caught for x={}", x)),
    }
}

// --- Drop trait (аналог defer в Go) ---

struct Resource {
    name: String,
}

impl Resource {
    fn new(name: &str) -> Self {
        println!("  acquired: {}", name);
        Resource {
            name: name.to_string(),
        }
    }

    fn use_resource(&self) {
        println!("  using: {}", self.name);
    }
}

impl Drop for Resource {
    fn drop(&mut self) {
        println!("  released: {}", self.name);
    }
}

fn do_work_with_resources() {
    let r1 = Resource::new("database");
    let r2 = Resource::new("cache");

    r1.use_resource();
    r2.use_resource();

    println!("  -- end of scope --");
    // Drop вызывается в ОБРАТНОМ порядке (как defer в Go)
}

fn main() {
    // Result + ?
    println!("=== Result ===");
    for input in &["1", "2", "999", "abc", "0"] {
        match get_user_name(input) {
            Ok(name) => println!("  '{}' → {}", input, name),
            Err(e) => println!("  '{}' → ERROR: {}", input, e),
        }
    }

    // Обработка конкретного варианта ошибки
    println!("\n=== Match on error variant ===");
    let result = get_user_name("999");
    match result {
        Ok(name) => println!("  {}", name),
        Err(AppError::NotFound { entity, id }) => {
            println!("  {} #{} not in database", entity, id);
        }
        Err(e) => println!("  other error: {}", e),
    }

    // catch_unwind
    println!("\n=== Panic recovery ===");
    println!("  safe_call(5) = {:?}", safe_call(5));
    println!("  safe_call(-1) = {:?}", safe_call(-1));

    // Drop
    println!("\n=== Drop (defer) ===");
    do_work_with_resources();
    println!("after function returned");
}

