# Задание 1: Декораторы — retry, timing, кэширование

import time
import functools
from typing import Any, Callable

# --- Декоратор 1: замер времени выполнения ---

def timing(func: Callable) -> Callable:
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f"{func.__name__} took {elapsed:.4f}s")
        return result
    return wrapper

# --- Декоратор 2: retry с количеством попыток ---

def retry(max_attempts: int = 3, delay: float = 0.1):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    last_error = e
                    print(f"attempt {attempt} failed: {e}")
                    if attempt < max_attempts:
                        time.sleep(delay)
            raise last_error
        return wrapper
    return decorator

# --- Декоратор 3: кэширование результатов ---

def memoize(func: Callable) -> Callable:
    cache: dict[tuple, Any] = {}

    @functools.wraps(func)
    def wrapper(*args):
        if args in cache:
            print(f"cache hit for {args}")
            return cache[args]
        result = func(*args)
        cache[args] = result
        return result
    return wrapper

# --- Использование ---

@timing
def slow_add(a: int, b: int) -> int:
    time.sleep(0.1)
    return a + b

call_count = 0

@retry(max_attempts=5, delay=0.05)
def flaky_function():
    global call_count
    call_count += 1
    if call_count < 3:
        raise ValueError("not ready yet")
    return "success"

@memoize
def fibonacci(n: int) -> int:
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

if __name__ == "__main__":
    # Timing
    result = slow_add(2, 3)
    print(f"result: {result}\n")

    # Retry
    print(flaky_function())
    print()

    # Memoize
    print(f"fib(10) = {fibonacci(10)}")
    print(f"fib(10) = {fibonacci(10)}")  # второй вызов — из кэша

# Задание 5: dataclasses, __slots__, property, __post_init__

from dataclasses import dataclass, field
from typing import ClassVar

# --- Базовый dataclass ---

@dataclass
class Point:
    x: float
    y: float

    def distance_to(self, other: "Point") -> float:
        return ((self.x - other.x) ** 2 + (self.y - other.y) ** 2) ** 0.5

# --- dataclass с дефолтами и __post_init__ ---

@dataclass
class User:
    name: str
    age: int
    email: str = ""
    tags: list[str] = field(default_factory=list)
    _display_name: str = field(init=False, repr=False)

    # Счётчик экземпляров — общий для класса
    _count: ClassVar[int] = 0

    def __post_init__(self):
        self._display_name = f"{self.name} (age {self.age})"
        User._count += 1

    @property
    def display_name(self) -> str:
        return self._display_name

    @display_name.setter
    def display_name(self, value: str):
        self._display_name = value

    @classmethod
    def get_count(cls) -> int:
        return cls._count

# --- frozen dataclass (неизменяемый) ---

@dataclass(frozen=True)
class Config:
    host: str
    port: int
    debug: bool = False

    def url(self) -> str:
        proto = "http" if not self.debug else "https"
        return f"{proto}://{self.host}:{self.port}"

# --- __slots__ для оптимизации памяти ---

@dataclass(slots=True)
class Sensor:
    id: int
    value: float
    unit: str = "°C"

    def reading(self) -> str:
        return f"Sensor {self.id}: {self.value}{self.unit}"

# --- Наследование dataclass ---

@dataclass
class Shape:
    name: str
    color: str = "black"

@dataclass
class Circle(Shape):
    radius: float = 1.0

    @property
    def area(self) -> float:
        import math
        return math.pi * self.radius ** 2

@dataclass
class Rectangle(Shape):
    width: float = 1.0
    height: float = 1.0

    @property
    def area(self) -> float:
        return self.width * self.height

if __name__ == "__main__":
    # Point
    p1 = Point(0, 0)
    p2 = Point(3, 4)
    print(f"{p1} → {p2} distance: {p1.distance_to(p2):.2f}")
    print()

    # User
    u1 = User("Alice", 30, email="alice@test.com")
    u2 = User("Bob", 25, tags=["admin", "dev"])
    print(u1)
    print(f"display: {u1.display_name}")
    u1.display_name = "Alice Smith"
    print(f"updated: {u1.display_name}")
    print(f"total users: {User.get_count()} ")
    print()

    # Config (frozen)
    cfg = Config("localhost", 8080)
    print(cfg.url())
    try:
        cfg.port = 9090  # должно упасть — frozen
    except Exception:
        print("cannot modify frozen dataclass")
    print()

    # Sensor (slots)
    s = Sensor(id=1, value=23.5)
    print(s.reading())
    try:
        s.extra = "oops"  # slots не позволяет
    except AttributeError:
        print("slots: cannot add attributes")
    print()

    # Наследование
    c = Circle(name="disk", color="red", radius=5.0)
    r = Rectangle(name="box", width=3, height=4)
    print(f"{c.name}: area={c.area:.2f}")
    print(f"{r.name}: area={r.area:.2f}")

# Задание 7: Метаклассы и дескрипторы

from typing import Any

# --- Дескриптор: валидация типа ---

class TypedField:
    """Дескриптор, который проверяет тип при присваивании"""

    def __init__(self, name: str, expected_type: type):
        self.name = name
        self.expected_type = expected_type

    def __set_name__(self, owner, name):
        self.attr_name = f"_{name}"

    def __get__(self, obj, objtype=None) -> Any:
        if obj is None:
            return self
        return getattr(obj, self.attr_name, None)

    def __set__(self, obj, value):
        if not isinstance(value, self.expected_type):
            raise TypeError(
                f"{self.name} must be {self.expected_type.__name__}, "
                f"got {type(value).__name__}"
            )
        setattr(obj, self.attr_name, value)

# --- Дескриптор: ограничение диапазона ---

class RangeField:
    def __init__(self, name: str, min_val: float, max_val: float):
        self.name = name
        self.min_val = min_val
        self.max_val = max_val

    def __set_name__(self, owner, name):
        self.attr_name = f"_{name}"

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return getattr(obj, self.attr_name, None)

    def __set__(self, obj, value):
        if not (self.min_val <= value <= self.max_val):
            raise ValueError(
                f"{self.name} must be between {self.min_val} and {self.max_val}, got {value}"
            )
        setattr(obj, self.attr_name, value)

# --- Класс с дескрипторами ---

class Product:
    name = TypedField("name", str)
    price = RangeField("price", 0, 1000000)
    quantity = RangeField("quantity", 0, 10000)

    def __init__(self, name: str, price: float, quantity: int):
        self.name = name
        self.price = price
        self.quantity = quantity

    def total(self) -> float:
        return self.price * self.quantity

# --- Метакласс: автоматическая регистрация подклассов ---

class RegistryMeta(type):
    _registry: dict[str, type] = {}

    def __new__(mcs, name, bases, namespace):
        cls = super().__new__(mcs, name, bases, namespace)
        if bases:  # не регистрируем сам базовый класс
            mcs._registry[name] = cls
        return cls

    @classmethod
    def get_registry(mcs) -> dict[str, type]:
        return dict(mcs._registry)

# --- Базовый класс с метаклассом ---

class Plugin(metaclass=RegistryMeta):
    def execute(self) -> str:
        raise NotImplementedError("subclasses must implement execute()")

class AuthPlugin(Plugin):
    def execute(self) -> str:
        return "authenticating..."

class LogPlugin(Plugin):
    def execute(self) -> str:
        return "logging..."

class CachePlugin(Plugin):
    def execute(self) -> str:
        return "caching..."

if __name__ == "__main__":
    # Дескрипторы
    p = Product("Laptop", 999.99, 10)
    print(f"{p.name}: ${p.price} x {p.quantity} = ${p.total():.2f}")

    try:
        p.name = 123  # TypeError
    except TypeError as e:
        print(f"type error: {e}")

    try:
        p.price = -5  # ValueError — отрицательная цена
    except ValueError as e:
        print(f"range error: {e}")

    print()

    # Метакласс
    print("registered plugins:", list(RegistryMeta.get_registry().keys()))

    for name, cls in RegistryMeta.get_registry().items():
        plugin = cls()
        print(f"  {name}: {plugin.execute()}")

# Задание 8: ABC, Protocol, миксины

from abc import ABC, abstractmethod
from typing import Protocol, runtime_checkable

# --- ABC: абстрактный базовый класс ---

class Repository(ABC):
    """Абстрактный репозиторий — нельзя создать экземпляр напрямую"""

    @abstractmethod
    def get(self, id: int) -> dict | None:
        ...

    @abstractmethod
    def save(self, entity: dict) -> None:
        ...

    @abstractmethod
    def delete(self, id: int) -> bool:
        ...

    # Конкретный метод — наследуется
    def exists(self, id: int) -> bool:
        return self.get(id) is not None

# --- Конкретная реализация ---

class InMemoryRepo(Repository):
    def __init__(self):
        self._data: dict[int, dict] = {}

    def get(self, id: int) -> dict | None:
        return self._data.get(id)

    def save(self, entity: dict) -> None:
        entity_id = entity.get("id")
        if entity_id is None:
            raise ValueError("entity must have 'id'")
        self._data[entity_id] = entity

    def delete(self, id: int) -> bool:
        if id in self._data:
            del self._data[id]
            return True
        return False

# --- Protocol: структурная типизация (duck typing) ---

@runtime_checkable
class Printable(Protocol):
    def to_string(self) -> str:
        ...

class User:
    def __init__(self, name: str, role: str):
        self.name = name
        self.role = role

    def to_string(self) -> str:
        return f"User({self.name}, role={self.role})"

class Product:
    def __init__(self, title: str, price: float):
        self.title = title
        self.price = price

    def to_string(self) -> str:
        return f"Product({self.title}, ${self.price:.2f})"

class RawData:
    """НЕ реализует to_string"""
    pass

def print_item(item: Printable):
    print(item.to_string())

# --- Миксины ---

class JsonMixin:
    """Миксин: сериализация в JSON"""
    def to_json(self) -> str:
        import json
        return json.dumps(self.__dict__)

class ReprMixin:
    """Миксин: красивый __repr__"""
    def __repr__(self) -> str:
        attrs = ", ".join(f"{k}={v!r}" for k, v in self.__dict__.items())
        return f"{type(self).__name__}({attrs})"

class LogMixin:
    """Миксин: логирование вызовов"""
    def log(self, msg: str):
        print(f"[{type(self).__name__}] {msg}")

# Комбинируем миксины

class Order(JsonMixin, ReprMixin, LogMixin):
    def __init__(self, order_id: int, product: str, amount: float):
        self.order_id = order_id
        self.product = product
        self.amount = amount

if __name__ == "__main__":
    # ABC
    repo = InMemoryRepo()
    repo.save({"id": 1, "name": "Alice"})
    repo.save({"id": 2, "name": "Bob"})
    print(repo.get(1))
    print(f"exists(2): {repo.exists(2)}")
    print(f"delete(1): {repo.delete(1)}")
    print(f"exists(1): {repo.exists(1)}")

    try:
        _ = Repository()  # нельзя создать абстрактный класс
    except TypeError as e:
        print(f"ABC error: {e}")
    print()

    # Protocol
    user = User("Alice", "admin")
    prod = Product("Phone", 599.99)
    raw = RawData()

    print_item(user)
    print_item(prod)

    print(f"User is Printable: {isinstance(user, Printable)}")
    print(f"RawData is Printable: {isinstance(raw, Printable)}")
    print()

    # Миксины
    order = Order(order_id=42, product="laptop", amount=999.99)
    print(repr(order))      # ReprMixin
    print(order.to_json())  # JsonMixin
    order.log("created")    # LogMixin

