// Тема 9: Functions (Rust by Example)

// --- 9.1 Базовые функции ---

fn is_divisible_by(lhs: u32, rhs: u32) -> bool {
    if rhs == 0 {
        return false;
    }
    lhs % rhs == 0
}

fn fizzbuzz(n: u32) -> () {
    if is_divisible_by(n, 15) {
        println!("fizzbuzz");
    } else if is_divisible_by(n, 3) {
        println!("fizz");
    } else if is_divisible_by(n, 5) {
        println!("buzz");
    } else {
        println!("{}", n);
    }
}

fn fizzbuzz_to(n: u32) {
    for i in 1..=n {
        fizzbuzz(i);
    }
}

// --- 9.2 Closures ---

fn closure_basics() {
    let outer_var = 42;

    // Замыкание с аннотацией типов
    let closure_annotated = |i: i32| -> i32 { i + outer_var };

    // Замыкание с выводом типов (без аннотации)
    let closure_inferred = |i| i + outer_var;

    println!("annotated: {}", closure_annotated(1));
    println!("inferred: {}", closure_inferred(1));

    // Замыкание без аргументов
    let one = || 1;
    println!("one: {}", one());
}

// --- 9.2.1 Capturing ---

fn capture_demo() {
    let color = String::from("green");

    // Захват по иммутабельной ссылке (&)
    let print = || println!("`color`: {}", color);
    print();

    // color всё ещё доступен — замыкание держит только &color
    let _reborrow = &color;
    print();

    // --- Мутабельный захват ---
    let mut count = 0;

    // mut нужен потому что замыкание захватывает &mut count
    let mut inc = || {
        count += 1;
        println!("`count`: {}", count);
    };

    inc();
    inc();

    // После последнего вызова inc — можно снова заимствовать count
    let _count_reborrowed = &mut count;

    // --- Захват по значению (move) ---
    let movable = Box::new(3);

    let consume = || {
        println!("`movable`: {:?}", movable);
        std::mem::drop(movable);
    };

    consume();
    // consume(); // ← нельзя вызвать второй раз!
}

// --- 9.2.2 move keyword ---

fn move_demo() {
    let haystack = vec![1, 2, 3];

    // move принуждает захват по значению
    let contains = move |needle| haystack.contains(needle);

    println!("{}", contains(&1));
    println!("{}", contains(&4));

    // haystack больше недоступен — он перемещён в замыкание
    // println!("{}", haystack.len()); // ← ошибка!
}

// --- 9.2.3 As input parameters: Fn, FnMut, FnOnce ---

fn apply<F>(f: F)
where
    F: FnOnce(), // замыкание без аргументов, вызывается один раз
{
    f();
}

fn apply_to_3<F>(f: F) -> i32
where
    F: Fn(i32) -> i32, // замыкание: i32 → i32, можно вызывать многократно
{
    f(3)
}

fn input_params_demo() {
    use std::mem;

    let greeting = "hello";
    let mut farewell = "goodbye".to_owned();

    let diary = || {
        // greeting по ссылке → Fn
        println!("I said {}.", greeting);

        // мутация → FnMut
        farewell.push_str("!!!");
        println!("Then I screamed {}.", farewell);

        // drop → FnOnce
        mem::drop(farewell);
    };

    apply(diary);

    let double = |x| 2 * x;
    println!("3 doubled: {}", apply_to_3(double));
}

// --- 9.2.4 Input functions (обычная функция как параметр) ---

fn call_me<F: Fn()>(f: F) {
    f();
}

fn i_am_a_function() {
    println!("I'm a function!");
}

fn input_functions_demo() {
    let closure = || println!("I'm a closure!");
    call_me(closure);
    call_me(i_am_a_function);
}

// --- 9.2.5 As output parameters ---

fn create_fn() -> impl Fn() {
    let text = "Fn".to_owned();
    move || println!("This is a: {}", text)
}

fn create_fnmut() -> impl FnMut() {
    let text = "FnMut".to_owned();
    move || println!("This is a: {}", text)
}

fn create_fnonce() -> impl FnOnce() {
    let text = "FnOnce".to_owned();
    move || println!("This is a: {}", text)
}

fn output_params_demo() {
    let fn_plain = create_fn();
    let mut fn_mut = create_fnmut();
    let fn_once = create_fnonce();

    fn_plain();
    fn_mut();
    fn_once();
}

// --- 9.3 Diverging functions ---

fn _diverge() -> ! {
    panic!("This call never returns.");
}

fn sum_odd_numbers(up_to: u32) -> u32 {
    let mut acc = 0;
    for i in 0..up_to {
        let addition: u32 = match i % 2 == 1 {
            true => i,
            false => continue, // continue — diverging, совместим с любым типом
        };
        acc += addition;
    }
    acc
}

fn main() {
    println!("=== FizzBuzz ===");
    fizzbuzz_to(15);

    println!("\n=== Closures ===");
    closure_basics();

    println!("\n=== Capture ===");
    capture_demo();

    println!("\n=== Move ===");
    move_demo();

    println!("\n=== Input params ===");
    input_params_demo();

    println!("\n=== Input functions ===");
    input_functions_demo();

    println!("\n=== Output params ===");
    output_params_demo();

    println!("\n=== Diverging ===");
    println!("Sum of odd numbers up to 9: {}", sum_odd_numbers(9));
}

