# Задание 9: collections — defaultdict, Counter, deque, OrderedDict, namedtuple

from collections import defaultdict, Counter, deque, OrderedDict, namedtuple

# --- defaultdict: группировка ---

def group_by_length(words: list[str]) -> dict[int, list[str]]:
    """Группирует слова по длине"""
    groups = defaultdict(list)
    for word in words:
        groups[len(word)].append(word)
    return dict(groups)

# --- defaultdict: граф ---

def build_graph(edges: list[tuple[str, str]]) -> dict[str, list[str]]:
    """Строит граф смежности из списка рёбер"""
    graph = defaultdict(list)
    for src, dst in edges:
        graph[src].append(dst)
        graph[dst].append(src)  # неориентированный граф
    return dict(graph)

# --- Counter: частотный анализ ---

def top_words(text: str, n: int) -> list[tuple[str, int]]:
    """Возвращает N самых частых слов"""
    words = text.lower().split()
    counter = Counter(words)
    return counter.most_common(n)

def common_between(list1: list, list2: list) -> list:
    """Общие элементы с учётом количества: [1,1,2] & [1,1,3] → [1,1]"""
    c1 = Counter(list1)
    c2 = Counter(list2)
    common = c1 & c2  # оператор пересечения Counter
    return list(common.elements())

# --- deque: ограниченный буфер ---

class RecentHistory:
    """Хранит последние N элементов"""

    def __init__(self, max_size: int):
        self._buffer: deque = deque(maxlen=max_size)

    def add(self, item):
        self._buffer.append(item)

    def get_all(self) -> list:
        return list(self._buffer)

    @property
    def latest(self):
        return self._buffer[-1] if self._buffer else None

    @property
    def oldest(self):
        return self._buffer[0] if self._buffer else None

# --- deque: BFS ---

def bfs_shortest_path(graph: dict, start: str, end: str) -> list[str] | None:
    """BFS поиск кратчайшего пути в графе"""
    visited = {start}
    queue = deque([(start, [start])])

    while queue:
        node, path = queue.popleft()
        if node == end:
            return path
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    return None

# --- namedtuple ---

Point = namedtuple("Point", ["x", "y"])
Color = namedtuple("Color", "r g b")

class Pixel(Color):
    """Расширяем namedtuple"""

    @property
    def brightness(self) -> float:
        return (self.r + self.g + self.b) / 3 / 255

    def hex(self) -> str:
        return f"#{self.r:02x}{self.g:02x}{self.b:02x}"

# --- OrderedDict: LRU (упрощённый) ---

class SimpleLRU:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key: str) -> str | None:
        if key not in self.cache:
            return None
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key: str, value: str):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

if __name__ == "__main__":
    # group_by_length
    words = ["hi", "cat", "go", "dog", "hello", "ant", "world"]
    print("by length:", group_by_length(words))
    print()

    # граф + BFS
    edges = [("A", "B"), ("B", "C"), ("A", "D"), ("D", "C"), ("C", "E")]
    graph = build_graph(edges)
    print("graph:", graph)
    path = bfs_shortest_path(graph, "A", "E")
    print(f"A → E: {path}")
    print()

    # Counter
    text = "the cat sat on the mat the cat"
    print("top 2:", top_words(text, 2))
    print("common:", common_between([1, 1, 2, 3], [1, 1, 2, 4]))
    print()

    # RecentHistory
    history = RecentHistory(max_size=3)
    for cmd in ["ls", "cd", "git status", "make", "python app.py"]:
        history.add(cmd)
    print(f"history: {history.get_all()}")
    print(f"latest: {history.latest}")
    print(f"oldest: {history.oldest}")
    print()

    # namedtuple
    p = Point(3, 4)
    print(f"point: x={p.x} y={p.y}")

    px = Pixel(255, 128, 0)
    print(f"pixel: {px.hex()}, brightness={px.brightness:.2f}")
    print()

    # SimpleLRU
    lru = SimpleLRU(capacity=3)
    lru.put("a", "1")
    lru.put("b", "2")
    lru.put("c", "3")
    print(f"get a: {lru.get('a')}")  # обновляет позицию
    lru.put("d", "4")  # вытеснит "b" (самый старый)
    print(f"get b: {lru.get('b')}")  # None
    print(f"get c: {lru.get('c')}")  # 3

