// Тема 10: Modules (Rust by Example)

// --- 10.1 Visibility ---

mod my_mod {
    // По умолчанию — private
    fn private_function() {
        println!("called `my_mod::private_function()`");
    }

    // pub делает функцию публичной
    pub fn function() {
        println!("called `my_mod::function()`");
    }

    // Приватные элементы доступны внутри того же модуля
    pub fn indirect_access() {
        print!("called `my_mod::indirect_access()`, that\n> ");
        private_function(); // вызываем приватную функцию
    }

    // Вложенный модуль
    pub mod nested {
        pub fn function() {
            println!("called `my_mod::nested::function()`");
        }

        #[allow(dead_code)]
        fn private_function() {
            println!("called `my_mod::nested::private_function()`");
        }

        // Видна только внутри crate::my_mod
        pub(in crate::my_mod) fn public_function_in_my_mod() {
            print!("called `my_mod::nested::public_function_in_my_mod()`, that\n> ");
            public_function_in_nested();
        }

        // pub(self) = private (видна только в текущем модуле)
        pub(self) fn public_function_in_nested() {
            println!("called `my_mod::nested::public_function_in_nested()`");
        }

        // pub(super) = видна в родительском модуле
        pub(super) fn public_function_in_super_mod() {
            println!("called `my_mod::nested::public_function_in_super_mod()`");
        }
    }

    pub fn call_public_function_in_my_mod() {
        print!("called `my_mod::call_public_function_in_my_mod()`, that\n> ");
        nested::public_function_in_my_mod();
        print!("> ");
        nested::public_function_in_super_mod();
    }

    // pub(crate) = видна во всём крейте, но не снаружи
    pub(crate) fn public_function_in_crate() {
        println!("called `my_mod::public_function_in_crate()`");
    }

    // Приватный вложенный модуль
    mod private_nested {
        #[allow(dead_code)]
        pub fn function() {
            println!("called `my_mod::private_nested::function()`");
        }
    }
}

// --- 10.2 Struct visibility ---

mod my {
    // Публичная структура с публичным полем
    pub struct OpenBox<T> {
        pub contents: T,
    }

    // Публичная структура с приватным полем
    pub struct ClosedBox<T> {
        contents: T, // приватное поле!
    }

    impl<T> ClosedBox<T> {
        // Публичный конструктор — единственный способ создать ClosedBox
        pub fn new(contents: T) -> ClosedBox<T> {
            ClosedBox { contents: contents }
        }
    }
}

// --- 10.3 The use declaration ---

// use позволяет обращаться без полного пути.
// Чтобы не конфликтовать с локальной `fn function()`, импортируем под псевдонимом.
use crate::my_mod::nested::function as nested_function;

mod deeply {
    pub mod nested {
        pub fn function() {
            println!("called `deeply::nested::function()`");
        }
    }
}

// Переименование при импорте
use deeply::nested::function as other_function;

// --- 10.4 super and self ---

mod parent {
    fn function() {
        println!("called `parent::function()`");
    }

    mod cool {
        pub fn function() {
            println!("called `parent::cool::function()`");
        }
    }

    pub fn indirect_call() {
        print!("called `parent::indirect_call()`, that\n> ");

        // self:: = текущий модуль
        self::function();

        // Можно и без self — то же самое
        function();

        // self:: для доступа к вложенному модулю
        self::cool::function();

        // super:: = родительский модуль
        super::outer_function();
    }
}

fn outer_function() {
    println!("called `outer_function()`");
}

fn function() {
    println!("called `function()`");
}

fn main() {
    // --- Visibility ---
    println!("=== Visibility ===");
    function();
    my_mod::function();
    my_mod::indirect_access();
    my_mod::nested::function();
    my_mod::call_public_function_in_my_mod();
    my_mod::public_function_in_crate(); // pub(crate) — доступна внутри крейта

    // Ошибки (раскомментируй чтобы увидеть):
    // my_mod::private_function();                       // приватная!
    // my_mod::nested::private_function();               // приватная!
    // my_mod::nested::public_function_in_my_mod();      // pub(in crate::my_mod)

    // --- Struct visibility ---
    println!("\n=== Struct visibility ===");
    let open_box = my::OpenBox {
        contents: "public info",
    };
    println!("open box: {}", open_box.contents);

    // Нельзя: let closed = my::ClosedBox { contents: "secret" };
    // Только через конструктор:
    let _closed_box = my::ClosedBox::new("classified");

    // Нельзя: println!("{}", _closed_box.contents);  // поле приватное!

    // --- use ---
    println!("\n=== use ===");
    nested_function(); // используем импортированную функцию из nested
    other_function(); // используем переименованную функцию

    // --- super / self ---
    println!("\n=== super / self ===");
    parent::indirect_call();
}

// Тема 11: Crates (Rust by Example)
//
// Крейт (crate) — единица компиляции в Rust.
// Бывает два типа: binary (исполняемый) и library (библиотека).
//
// Эта задача содержит два файла:
//   1. rary.rs — библиотека
//   2. этот файл — бинарник, использующий библиотеку
//
// Компиляция:
//   $ rustc --crate-type=lib rary.rs
//   $ rustc 11_crates.rs --extern rary=library.rlib

// ========== Файл: rary.rs (библиотека) ==========
// Раскомментируй мысленно — это отдельный файл.
//
// pub fn public_function() {
//     println!("called rary's `public_function()`");
// }
//
// fn private_function() {
//     println!("called rary's `private_function()`");
// }
//
// pub fn indirect_access() {
//     print!("called rary's `indirect_access()`, that\n> ");
//     private_function();
// }

// ========== Этот файл: использование библиотеки ==========

// В Rust 2015 нужно: extern crate rary;
// В Rust 2018+ достаточно просто использовать имя крейта.

// Чтобы задача компилировалась standalone — имитируем библиотеку модулем:

mod rary {
    pub fn public_function() {
        println!("called rary's `public_function()`");
    }

    // Приватная — недоступна снаружи модуля
    fn private_function() {
        println!("called rary's `private_function()`");
    }

    pub fn indirect_access() {
        print!("called rary's `indirect_access()`, that\n> ");
        private_function(); // приватная функция доступна внутри модуля
    }

    // --- Расширим библиотеку: публичная структура ---

    pub struct Config {
        pub name: String, // публичное поле
        version: String,  // приватное поле
    }

    impl Config {
        pub fn new(name: &str, version: &str) -> Self {
            Config {
                name: name.to_string(),
                version: version.to_string(),
            }
        }

        pub fn info(&self) -> String {
            format!("{} v{}", self.name, self.version)
        }
    }

    // --- Вложенный публичный модуль ---

    pub mod utils {
        pub fn add(a: i32, b: i32) -> i32 {
            a + b
        }

        pub fn greet(name: &str) {
            println!("Hello, {}!", name);
        }

        // Приватная функция — недоступна снаружи utils
        fn _helper() -> &'static str {
            "internal"
        }

        pub fn use_helper() -> &'static str {
            _helper()
        }
    }

    // --- Реэкспорт (pub use) ---
    // Делаем utils::add доступной напрямую через rary::add
    pub use self::utils::add;
}

// --- use для удобства ---

use rary::utils::greet; // импортируем greet напрямую
use rary::Config as config; // переименовываем Config

fn main() {
    println!("=== Basic library usage ===");
    rary::public_function();
    // rary::private_function();  // ← ошибка! приватная
    rary::indirect_access();

    println!("\n=== Struct from library ===");
    let cfg = config::new("MyApp", "1.0.0");
    println!("config: {}", cfg.info());
    println!("name: {}", cfg.name);
    // println!("version: {}", cfg.version);  // ← ошибка! приватное поле

    println!("\n=== Nested module ===");
    let sum = rary::utils::add(2, 3);
    println!("2 + 3 = {}", sum);

    // Используем импортированную greet
    greet("Rustacean");

    // Реэкспорт — add доступен напрямую через rary::
    let sum2 = rary::add(10, 20);
    println!("10 + 20 = {}", sum2);

    println!("\n=== Helper через pub fn ===");
    println!("helper says: {}", rary::utils::use_helper());
    // rary::utils::_helper();  // ← ошибка! приватная

    println!("\n=== Recap ===");
    println!("pub fn       → доступна снаружи");
    println!("fn (no pub)  → только внутри модуля");
    println!("pub struct   → структура доступна, но поля могут быть приватными");
    println!("pub use      → реэкспорт элемента по короткому пути");
    println!("--crate-type=lib → компилирует .rlib библиотеку");
}

