# Задание 13: typing — Generic, TypeVar, overload, TypeGuard

from __future__ import annotations
from typing import (
    Generic,
    TypeVar,
    overload,
    TypeGuard,
    Callable,
    Any,
    Iterator,
)

# --- TypeVar и Generic: типобезопасный стек ---

T = TypeVar("T")

class Stack(Generic[T]):
    def __init__(self):
        self._items: list[T] = []

    def push(self, item: T) -> None:
        self._items.append(item)

    def pop(self) -> T:
        if self.is_empty():
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self) -> T:
        if self.is_empty():
            raise IndexError("peek at empty stack")
        return self._items[-1]

    def is_empty(self) -> bool:
        return len(self._items) == 0

    def __len__(self) -> int:
        return len(self._items)

    def __iter__(self) -> Iterator[T]:
        return iter(reversed(self._items))

# --- Generic с двумя параметрами: Result ---

E = TypeVar("E", bound=Exception)

class Result(Generic[T, E]):
    def __init__(self, value: T | None = None, error: E | None = None):
        self._value = value
        self._error = error

    @property
    def is_ok(self) -> bool:
        return self._error is None

    def unwrap(self) -> T:
        if not self.is_ok:
            raise RuntimeError(f"unwrap on error: {self._error}")
        return self._value  # type: ignore

    def unwrap_err(self) -> E:
        if self.is_ok:
            raise RuntimeError("unwrap_err on ok")
        return self._error  # type: ignore

    def map(self, func: Callable[[T], Any]) -> Result:
        if not self.is_ok:
            return self
        try:
            return Result(value=func(self._value))
        except Exception as e:
            return Result(error=e)

    @classmethod
    def ok(cls, value: T) -> Result[T, Any]:
        return cls(value=value)

    @classmethod
    def err(cls, error: E) -> Result[Any, E]:
        return cls(error=error)

# --- overload: разные сигнатуры ---

@overload
def parse(data: str) -> dict: ...

@overload
def parse(data: bytes) -> str: ...

@overload
def parse(data: list) -> list[dict]: ...

def parse(data: str | bytes | list) -> dict | str | list[dict]:
    if isinstance(data, str):
        return {"parsed": data}
    elif isinstance(data, bytes):
        return data.decode("utf-8")
    elif isinstance(data, list):
        return [{"item": x} for x in data]
    raise TypeError(f"unsupported type: {type(data)}")

# --- TypeGuard: сужение типов ---

def is_string_list(val: list[Any]) -> TypeGuard[list[str]]:
    return all(isinstance(item, str) for item in val)

def process_items(items: list[Any]) -> str:
    if is_string_list(items):
        # Здесь mypy знает что items: list[str]
        return ", ".join(items)
    return str(items)

# --- Generic функция: pipe ---

A = TypeVar("A")
B = TypeVar("B")

def pipe(value: A, *funcs: Callable) -> Any:
    result = value
    for func in funcs:
        result = func(result)
    return result

if __name__ == "__main__":
    # Stack
    print("=== Generic Stack ===")
    int_stack: Stack[int] = Stack()
    int_stack.push(1)
    int_stack.push(2)
    int_stack.push(3)
    print(f"peek: {int_stack.peek()}")
    print(f"pop: {int_stack.pop()}")
    print(f"len: {len(int_stack)}")
    print(f"items: {list(int_stack)}")
    print()

    str_stack: Stack[str] = Stack()
    str_stack.push("hello")
    str_stack.push("world")
    print(f"str peek: {str_stack.peek()}")
    print()

    # Result
    print("=== Result[T, E] ===")
    ok = Result.ok(42)
    err = Result.err(ValueError("oops"))

    print(f"ok: is_ok={ok.is_ok}, value={ok.unwrap()}")
    print(f"err: is_ok={err.is_ok}, error={err.unwrap_err()}")

    chained = ok.map(lambda x: x * 2).map(str)
    print(f"chained: {chained.unwrap()}")
    print()

    # overload
    print("=== Overload ===")
    print(parse("hello"))
    print(parse(b"world"))
    print(parse([1, 2, 3]))
    print()

    # TypeGuard
    print("=== TypeGuard ===")
    print(process_items(["a", "b", "c"]))
    print(process_items([1, "mixed", 3]))
    print()

    # pipe
    print("=== Pipe ===")
    result = pipe(
        "  Hello World  ",
        str.strip,
        str.lower,
        lambda s: s.replace(" ", "_"),
    )
    print(f"pipe result: {result}")

# Задание 14: functools и itertools — продвинутое функциональное программирование

import functools
import itertools
import operator
from typing import Any, Callable, Iterator

# --- functools.reduce ---

def my_sum(numbers: list[int]) -> int:
    return functools.reduce(operator.add, numbers, 0)

def flatten(nested: list[list]) -> list:
    return functools.reduce(operator.add, nested, [])

def compose(*funcs: Callable) -> Callable:
    """Композиция функций: compose(f, g, h)(x) = f(g(h(x)))"""
    def composed(x):
        return functools.reduce(
            lambda acc, f: f(acc),
            reversed(funcs),
            x,
        )
    return composed

# --- functools.partial ---

def power(base: int, exp: int) -> int:
    return base ** exp

square = functools.partial(power, exp=2)
cube = functools.partial(power, exp=3)

# --- functools.lru_cache ---

@functools.lru_cache(maxsize=128)
def fibonacci(n: int) -> int:
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

# --- functools.total_ordering ---

@functools.total_ordering
class Money:
    def __init__(self, amount: float, currency: str = "USD"):
        self.amount = amount
        self.currency = currency

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Money):
            return NotImplemented
        return self.amount == other.amount and self.currency == other.currency

    def __lt__(self, other: "Money") -> bool:
        if self.currency != other.currency:
            raise ValueError("cannot compare different currencies")
        return self.amount < other.amount

    def __repr__(self) -> str:
        return f"Money({self.amount}, '{self.currency}')"

# --- itertools: бесконечные итераторы ---

def take(n: int, iterable: Iterator) -> list:
    """Берёт первые n элементов"""
    return list(itertools.islice(iterable, n))

def fibonacci_gen() -> Iterator[int]:
    """Бесконечный генератор Фибоначчи"""
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b

# --- itertools: комбинаторика ---

def all_pairs(items: list) -> list[tuple]:
    """Все уникальные пары"""
    return list(itertools.combinations(items, 2))

def all_triples(items: list) -> list[tuple]:
    """Все комбинации по 3 с повторениями"""
    return list(itertools.combinations_with_replacement(items, 3))

def cartesian(list1: list, list2: list) -> list[tuple]:
    """Декартово произведение"""
    return list(itertools.product(list1, list2))

# --- itertools: группировка и цепочки ---

def group_consecutive(data: list[int]) -> list[list[int]]:
    """Группирует последовательные одинаковые элементы"""
    result = []
    for key, group in itertools.groupby(data):
        result.append(list(group))
    return result

def chunked(iterable, size: int) -> Iterator[list]:
    """Разбивает итерируемое на чанки"""
    it = iter(iterable)
    while True:
        chunk = list(itertools.islice(it, size))
        if not chunk:
            break
        yield chunk

def chain_iterables(*iterables) -> list:
    """Склеивает несколько итерируемых в один список"""
    return list(itertools.chain.from_iterable(iterables))

# --- itertools: accumulate ---

def running_max(numbers: list[int]) -> list[int]:
    return list(itertools.accumulate(numbers, max))

def running_product(numbers: list[int]) -> list[int]:
    return list(itertools.accumulate(numbers, operator.mul))

if __name__ == "__main__":
    # reduce
    print("=== reduce ===")
    print(f"sum: {my_sum([1, 2, 3, 4, 5])}")
    print(f"flatten: {flatten([[1, 2], [3, 4], [5]])}")

    transform = compose(str.upper, str.strip, lambda s: s + "!")
    print(f"compose: {transform('  hello  ')}")
    print()

    # partial
    print("=== partial ===")
    print(f"square(5): {square(5)}")
    print(f"cube(3): {cube(3)}")
    print()

    # lru_cache
    print("=== lru_cache ===")
    print(f"fib(30): {fibonacci(30)}")
    print(f"cache info: {fibonacci.cache_info()}")
    fibonacci.cache_clear()  # очистить кэш
    print()

    # total_ordering
    print("=== total_ordering ===")
    m1 = Money(10)
    m2 = Money(20)
    m3 = Money(10)
    print(f"{m1} < {m2}: {m1 < m2}")
    print(f"{m1} >= {m3}: {m1 >= m3}")
    print(f"{m1} == {m3}: {m1 == m3}")
    print(f"sorted: {sorted([m2, m1, Money(15)])}")
    print()

    # itertools
    print("=== itertools ===")
    print(f"first 8 fib: {take(8, fibonacci_gen())}")
    print(f"pairs of [1,2,3]: {all_pairs([1, 2, 3])}")
    print(f"cartesian: {cartesian(['a','b'], [1, 2])}")
    print()

    print(f"group: {group_consecutive([1,1,2,2,2,3,1,1])}")
    print(f"chunks: {list(chunked(range(10), 3))}")
    print(f"chain: {chain_iterables([1,2], [3,4], [5])}")
    print()

    print(f"running max: {running_max([3,1,4,1,5,9,2,6])}")
    print(f"running product: {running_product([1,2,3,4])}")

# Задание 15: Dunder-методы — полная кастомизация поведения объектов

# === Vector: арифметика и сравнения ===

class Vector:
    def __init__(self, *components: float):
        self._data = list(components)

    # --- Строковое представление ---

    def __repr__(self) -> str:
        coords = ", ".join(f"{x:.1f}" for x in self._data)
        return f"Vector({coords})"

    def __str__(self) -> str:
        return f"({', '.join(str(x) for x in self._data)})"

    # --- Арифметика ---

    def __add__(self, other: "Vector") -> "Vector":
        if len(self) != len(other):
            raise ValueError("dimension mismatch")
        return Vector(*(a + b for a, b in zip(self._data, other._data)))

    def __sub__(self, other: "Vector") -> "Vector":
        return Vector(*(a - b for a, b in zip(self._data, other._data)))

    def __mul__(self, scalar: float) -> "Vector":
        """Умножение на скаляр: v * 3"""
        return Vector(*(x * scalar for x in self._data))

    def __rmul__(self, scalar: float) -> "Vector":
        """Обратное умножение: 3 * v"""
        return self.__mul__(scalar)

    def __neg__(self) -> "Vector":
        """Унарный минус: -v"""
        return Vector(*(-x for x in self._data))

    # --- Dot product через @ ---

    def __matmul__(self, other: "Vector") -> float:
        """Скалярное произведение: v1 @ v2"""
        return sum(a * b for a, b in zip(self._data, other._data))

    # --- Сравнения (по длине) ---

    def __abs__(self) -> float:
        """Длина вектора: abs(v)"""
        return sum(x ** 2 for x in self._data) ** 0.5

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Vector):
            return NotImplemented
        return self._data == other._data

    def __lt__(self, other: "Vector") -> bool:
        return abs(self) < abs(other)

    # --- Индексация ---

    def __len__(self) -> int:
        return len(self._data)

    def __getitem__(self, index: int) -> float:
        return self._data[index]

    def __setitem__(self, index: int, value: float):
        self._data[index] = value

    def __iter__(self):
        return iter(self._data)

    # --- bool и contains ---

    def __bool__(self) -> bool:
        """Нулевой вектор = False"""
        return any(x != 0 for x in self._data)

    def __contains__(self, value: float) -> bool:
        return value in self._data

# === Matrix: контейнер и callable ===

class Matrix:
    def __init__(self, rows: list[list[float]]):
        self._rows = [list(row) for row in rows]

    def __repr__(self) -> str:
        rows_str = ", ".join(str(row) for row in self._rows)
        return f"Matrix([{rows_str}])"

    # Размеры
    @property
    def shape(self) -> tuple[int, int]:
        return len(self._rows), len(self._rows[0]) if self._rows else 0

    # Доступ по [row][col]
    def __getitem__(self, row: int) -> list[float]:
        return self._rows[row]

    # Итерация по строкам
    def __iter__(self):
        return iter(self._rows)

    # len = количество строк
    def __len__(self) -> int:
        return len(self._rows)

    # Умножение матрицы на вектор
    def __call__(self, vec: Vector) -> Vector:
        """Применяем матрицу к вектору: m(v)"""
        if self.shape[1] != len(vec):
            raise ValueError("dimension mismatch")
        result = []
        for row in self._rows:
            val = sum(a * b for a, b in zip(row, vec))
            result.append(val)
        return Vector(*result)

    # Сравнение
    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Matrix):
            return NotImplemented
        return self._rows == other._rows

if __name__ == "__main__":
    # Vector
    print("=== Vector ===")
    v1 = Vector(1, 2, 3)
    v2 = Vector(4, 5, 6)

    print(f"repr: {repr(v1)}")
    print(f"str: {v1}")
    print(f"v1 + v2 = {v1 + v2}")
    print(f"v1 - v2 = {v1 - v2}")
    print(f"v1 * 3 = {v1 * 3}")
    print(f"3 * v1 = {3 * v1}")
    print(f"-v1 = {-v1}")
    print(f"v1 @ v2 = {v1 @ v2}")  # dot product
    print(f"|v1| = {abs(v1):.2f}")
    print(f"v1 < v2: {v1 < v2}")
    print(f"v1 == v1: {v1 == v1}")
    print(f"len: {len(v1)}")
    print(f"v1[0]: {v1[0]}")
    print(f"2 in v1: {2 in v1}")
    print(f"bool(Vector(0,0)): {bool(Vector(0, 0))}")
    print()

    # Итерация
    for component in v1:
        print(f"  component: {component}")
    print()

    # Matrix
    print("=== Matrix ===")
    m = Matrix([
        [1, 0, 0],
        [0, 2, 0],
        [0, 0, 3],
    ])
    print(f"shape: {m.shape}")
    print(f"m[1][1]: {m[1][1]}")
