// HTTP-сервер с подключённым net/http/pprof.
//
// Запуск:
//
//	go run main.go            # порт 8001
//	go run main.go 8080       # свой порт
//
// Эндпоинты приложения:
//
//	GET /                     — заглушка-обработчик
//	GET /time                 — текущее время
//	GET /hot                  — нагрузочный обработчик (жрёт CPU и память)
//
// Эндпоинты профилировщика:
//
//	GET /debug/pprof/         — индекс
//	GET /debug/pprof/profile  — CPU-профиль (30 сек по умолчанию)
//	GET /debug/pprof/heap     — снимок кучи
//	GET /debug/pprof/goroutine — все горутины
//	GET /debug/pprof/trace?seconds=5 — трассировка выполнения
//
// Сбор профилей:
//
//	go tool pprof http://localhost:8001/debug/pprof/profile
//	go tool pprof http://localhost:8001/debug/pprof/heap
//	go tool pprof -http=:9090 http://localhost:8001/debug/pprof/profile
//	curl -o trace.out 'http://localhost:8001/debug/pprof/trace?seconds=5'
//	go tool trace trace.out
package main

import (
	"crypto/sha256"
	"fmt"
	"math/rand"
	"net/http"
	"net/http/pprof"
	"os"
	"time"
)

func myHandler(w http.ResponseWriter, r *http.Request) {
	fmt.Fprintf(w, "Serving: %s\n", r.URL.Path)
	fmt.Printf("Served: %s\n", r.Host)
}

func timeHandler(w http.ResponseWriter, r *http.Request) {
	t := time.Now().Format(time.RFC1123)
	fmt.Fprintf(w, "The current time is: %s\n", t)
	fmt.Fprintf(w, "Serving: %s\n", r.URL.Path)
	fmt.Printf("Served time for: %s\n", r.Host)
}

// hotHandler специально нагружает CPU и аллоцирует память,
// чтобы в pprof было что посмотреть.
func hotHandler(w http.ResponseWriter, r *http.Request) {
	buf := make([]byte, 1<<20) // 1 MiB
	rand.Read(buf)

	sum := sha256.Sum256(buf)
	for i := 0; i < 50_000; i++ {
		sum = sha256.Sum256(sum[:])
	}

	fmt.Fprintf(w, "hot work done, hash prefix: %x\n", sum[:4])
}

func main() {
	port := ":8001"
	if len(os.Args) > 1 {
		port = ":" + os.Args[1]
		fmt.Println("Using port number:", port)
	} else {
		fmt.Println("Using default port number:", port)
	}

	r := http.NewServeMux()
	r.HandleFunc("/time", timeHandler)
	r.HandleFunc("/hot", hotHandler)
	r.HandleFunc("/", myHandler)

	// Регистрируем pprof-обработчики вручную, потому что используем свой mux.
	// Если бы использовали http.DefaultServeMux, импорта _ "net/http/pprof"
	// было бы достаточно.
	r.HandleFunc("/debug/pprof/", pprof.Index)
	r.HandleFunc("/debug/pprof/cmdline", pprof.Cmdline)
	r.HandleFunc("/debug/pprof/profile", pprof.Profile)
	r.HandleFunc("/debug/pprof/symbol", pprof.Symbol)
	r.HandleFunc("/debug/pprof/trace", pprof.Trace)

	fmt.Println("pprof index: http://localhost" + port + "/debug/pprof/")
	if err := http.ListenAndServe(port, r); err != nil {
		fmt.Println(err)
		return
	}
}

// CLI-программа со встроенной трассировкой через runtime/trace.
//
// Что делает: аллоцирует большие срезы, чтобы запустить GC и нагенерировать
// событий планировщика, затем останавливает трассировку и пишет файл.
//
// Запуск:
//
//	go run main.go
//
// Просмотр результата:
//
//	go tool trace /tmp/traceCLA.out
//	(откроется браузер с разделами View trace, Goroutine analysis,
//	 Network blocking profile, Syscall blocking profile, Scheduler latency)
//
// Аналог через `go test -trace`:
//
//	go test -trace=trace.out ./...
//	go tool trace trace.out
package main

import (
	"context"
	"fmt"
	"os"
	"path"
	"runtime/trace"
	"sync"
	"time"
)

func main() {
	filename := path.Join(os.TempDir(), "traceCLA.out")
	f, err := os.Create(filename)
	if err != nil {
		panic(err)
	}
	defer f.Close()

	if err := trace.Start(f); err != nil {
		fmt.Println(err)
		return
	}
	defer trace.Stop()

	fmt.Println("Tracing to:", filename)

	// Фаза 1: короткие аллокации — провоцируем GC.
	for i := 0; i < 3; i++ {
		s := make([]byte, 50_000_000)
		_ = s
	}

	// Фаза 2: аллокации + sleep, чтобы планировщику было что показать.
	for i := 0; i < 5; i++ {
		s := make([]byte, 100_000_000)
		_ = s
		time.Sleep(time.Millisecond)
	}

	// Фаза 3: горутины — чтобы во View trace появились параллельные дорожки.
	var wg sync.WaitGroup
	for i := 0; i < 8; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			region := trace.StartRegion(context.Background(), fmt.Sprintf("worker-%d", id))
			defer region.End()

			sum := 0
			for j := 0; j < 5_000_000; j++ {
				sum += j
			}
			_ = sum
		}(i)
	}
	wg.Wait()

	fmt.Println("Done. Run: go tool trace", filename)
}

// Профилирование обычной (не-HTTP) программы через runtime/pprof.
// Сравнить с пакетом net/http/pprof — здесь профили пишем сами в файлы.
//
// Запуск:
//
//	go run main.go -cpuprofile=cpu.out -memprofile=mem.out
//
// Анализ:
//
//	go tool pprof cpu.out
//	go tool pprof -http=:9090 cpu.out
//	go tool pprof -alloc_space mem.out
//	go tool pprof -inuse_space mem.out
//
// Полезные команды внутри pprof:
//
//	top              — топ функций по CPU/памяти
//	top -cum         — с учётом вызываемых функций
//	list funcName    — построчно посмотреть функцию
//	web              — открыть SVG-граф вызовов (нужен graphviz)
//	peek funcName    — кто вызывает / кого вызывает функция
package main

import (
	"flag"
	"fmt"
	"log"
	"os"
	"runtime"
	"runtime/pprof"
)

var (
	cpuprofile = flag.String("cpuprofile", "", "write cpu profile to file")
	memprofile = flag.String("memprofile", "", "write memory profile to file")
)

func fibonacci(n int) int {
	if n < 2 {
		return n
	}
	return fibonacci(n-1) + fibonacci(n-2)
}

func allocateGarbage() [][]byte {
	out := make([][]byte, 0, 100)
	for i := 0; i < 100; i++ {
		out = append(out, make([]byte, 1<<20)) // 1 MiB
	}
	return out
}

func main() {
	flag.Parse()

	if *cpuprofile != "" {
		f, err := os.Create(*cpuprofile)
		if err != nil {
			log.Fatal("could not create CPU profile:", err)
		}
		defer f.Close()
		if err := pprof.StartCPUProfile(f); err != nil {
			log.Fatal("could not start CPU profile:", err)
		}
		defer pprof.StopCPUProfile()
	}

	// CPU-нагрузка.
	for i := 0; i < 5; i++ {
		fmt.Println("fib(35) =", fibonacci(35))
	}

	// Память.
	keep := allocateGarbage()
	fmt.Println("allocated:", len(keep), "MiB-blocks")

	if *memprofile != "" {
		f, err := os.Create(*memprofile)
		if err != nil {
			log.Fatal("could not create memory profile:", err)
		}
		defer f.Close()
		runtime.GC() // освежить статистику живой памяти
		if err := pprof.WriteHeapProfile(f); err != nil {
			log.Fatal("could not write memory profile:", err)
		}
	}

	fmt.Println("done")
}

// Простой нагрузочный генератор для примера 01-http-pprof.
// Долбит /hot параллельными запросами, чтобы CPU-профиль был наполненным.
//
// Запуск:
//  1. терминал 1:  cd 01-http-pprof && go run main.go
//  2. терминал 2:  cd 04-load-generator && go run main.go
//  3. терминал 3:  go tool pprof -http=:9090 http://localhost:8001/debug/pprof/profile?seconds=15
package main

import (
	"flag"
	"fmt"
	"io"
	"net/http"
	"sync"
	"sync/atomic"
	"time"
)

func main() {
	url := flag.String("url", "http://localhost:8001/hot", "target URL")
	workers := flag.Int("workers", 16, "concurrent workers")
	duration := flag.Duration("duration", 30*time.Second, "test duration")
	flag.Parse()

	fmt.Printf("Hitting %s with %d workers for %s\n", *url, *workers, *duration)

	var (
		wg       sync.WaitGroup
		ok       atomic.Int64
		fail     atomic.Int64
		deadline = time.Now().Add(*duration)
		client   = &http.Client{Timeout: 30 * time.Second}
	)

	for i := 0; i < *workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for time.Now().Before(deadline) {
				resp, err := client.Get(*url)
				if err != nil {
					fail.Add(1)
					continue
				}
				io.Copy(io.Discard, resp.Body)
				resp.Body.Close()
				ok.Add(1)
			}
		}()
	}

	wg.Wait()
	fmt.Printf("ok=%d fail=%d\n", ok.Load(), fail.Load())
}

// Обход всех зарегистрированных маршрутов через gorilla/mux Walk().
//
// Идея: вешаем пустой обработчик на каждый маршрут, потом проходим по
// дереву роутера и печатаем шаблоны пути, регулярки, HTTP-методы.
// Это «неофициальный» способ проверить, что роутинг настроен так, как
// задумано — не упустили ли эндпоинт, не повесили ли GET вместо POST.
//
// Запуск:
//
//	go mod tidy
//	go run main.go
package main

import (
	"fmt"
	"net/http"
	"strings"

	"github.com/gorilla/mux"
)

func handler(w http.ResponseWriter, r *http.Request) {
	// Пустой обработчик — нам важна только регистрация маршрута.
}

type notAllowedHandler struct{}

func (h notAllowedHandler) ServeHTTP(rw http.ResponseWriter, r *http.Request) {
	handler(rw, r)
}

func main() {
	r := mux.NewRouter()
	r.NotFoundHandler = http.HandlerFunc(handler)
	r.MethodNotAllowedHandler = notAllowedHandler{}

	// GET — чтение
	getMux := r.Methods(http.MethodGet).Subrouter()
	getMux.HandleFunc("/time", handler)
	getMux.HandleFunc("/getall", handler)
	getMux.HandleFunc("/getid", handler)
	getMux.HandleFunc("/logged", handler)
	getMux.HandleFunc("/username/{id:[0-9]+}", handler)

	// PUT — обновление пользователя
	putMux := r.Methods(http.MethodPut).Subrouter()
	putMux.HandleFunc("/update", handler)

	// POST — добавить пользователя, вход и выход
	postMux := r.Methods(http.MethodPost).Subrouter()
	postMux.HandleFunc("/add", handler)
	postMux.HandleFunc("/login", handler)
	postMux.HandleFunc("/logout", handler)

	// DELETE — удалить пользователя
	deleteMux := r.Methods(http.MethodDelete).Subrouter()
	deleteMux.HandleFunc("/username/{id:[0-9]+}", handler)

	err := r.Walk(func(route *mux.Route, router *mux.Router, ancestors []*mux.Route) error {
		if pathTemplate, err := route.GetPathTemplate(); err == nil {
			fmt.Println("ROUTE:", pathTemplate)
		}
		if pathRegexp, err := route.GetPathRegexp(); err == nil {
			fmt.Println("Path regexp:", pathRegexp)
		}
		if qT, err := route.GetQueriesTemplates(); err == nil {
			fmt.Println("Queries templates:", strings.Join(qT, ","))
		}
		if qRegexps, err := route.GetQueriesRegexp(); err == nil {
			fmt.Println("Queries regexps:", strings.Join(qRegexps, ","))
		}
		if methods, err := route.GetMethods(); err == nil {
			fmt.Println("Methods:", strings.Join(methods, ","))
		}
		fmt.Println()
		return nil
	})
	if err != nil {
		fmt.Println(err)
	}

	http.Handle("/", r)
}

