// Snippet 1: Fan-in/Fan-out (merge)
func gen(data []int) <-chan int {
	ch := make(chan int)
	go func() {
		defer close(ch)
		for _, val := range data {
			ch <- val
		}
	}()
	return ch
}

func merge(chans ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup // Use WaitGroup to wait for all goroutines
	wg.Add(len(chans))

	for _, ch := range chans {
		go func(c <-chan int) {
			defer wg.Done()
			for val := range c {
				out <- val
			}
		}(ch)
	}

	go func() {
		wg.Wait()
		close(out) // Close the 'out' channel, not a loop variable
	}()
	return out
}

func mergeExample() {
	ch1 := gen([]int{1, 2, 3})
	ch2 := gen([]int{4, 5, 6})
	ch3 := gen([]int{7, 8, 9})

	merged := merge(ch1, ch2, ch3)

	for val := range merged { // Correct loop syntax
		fmt.Println(val)
	}
}

// Snippet 2: Parallel Processing with Context
func processData(v int) int {
	// Simulate work
	time.Sleep(time.Duration(rand.Intn(100)) * time.Millisecond)
	return v * 5
}

func processDataWithContext(ctx context.Context, v int) (int, bool) {
	ch := make(chan int)
	go func() {
		defer close(ch)
		ch <- processData(v)
	}()

	select {
	case <-ctx.Done():
		return 0, false // Return a value and indicate timeout
	case res := <-ch:
		return res, true
	}
}

func processParallel(ctx context.Context, in <-chan int, out chan<- int, numWorkers int) {
	var wg sync.WaitGroup
	wg.Add(numWorkers)
	for i := 0; i < numWorkers; i++ {
		go func() {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					return
				case v, ok := <-in:
					if !ok {
						return
					}
					if res, ok := processDataWithContext(ctx, v); ok {
						select {
						case <-ctx.Done():
							return
						case out <- res:
						}
					}
				}
			}
		}()
	}
	wg.Wait()
}

func processExample() {
	in := make(chan int)
	out := make(chan int)

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	// Producer
	go func() {
		defer close(in)
		for i := 0; i < 10; i++ {
			select {
			case <-ctx.Done():
				return
			case in <- i + 1:
			}
		}
	}()

	// Parallel processor
	go func() {
		processParallel(ctx, in, out, 5)
		close(out)
	}()

	// Consumer
	for v := range out {
		fmt.Println(v)
	}
}

