import (
	"context"
	"errors"
	"fmt"
	"math/rand"
	"sync"
	"time"
)

// ---------------- Stack ----------------

type Stack struct {
	items []string
}

func (s *Stack) Push(data string) {
	s.items = append(s.items, data)
}

func (s *Stack) Pop() (string, error) {
	if s.IsEmpty() {
		return "", errors.New("stack is empty")
	}
	top := s.items[len(s.items)-1]
	s.items = s.items[:len(s.items)-1]
	return top, nil
}

func (s *Stack) IsEmpty() bool {
	return len(s.items) == 0
}

func (s *Stack) Top() (string, error) {
	if s.IsEmpty() {
		return "", errors.New("stack is empty")
	}
	return s.items[len(s.items)-1], nil
}

// ---------------- Shared storage: collect unique ids concurrently ----------------

func uniqueIdsEx() {
	var wg sync.WaitGroup
	var mu sync.Mutex
	storage := make(map[int]struct{})
	const capacity = 1000
	arr := make([]int, 0, capacity)

	for i := 0; i < capacity; i++ {
		arr = append(arr, rand.Intn(5))
	}
	uniqueIds := make(chan int, capacity)

	for i := 0; i < capacity; i++ {
		wg.Add(1)
		go func(idx int) {
			defer wg.Done()
			mu.Lock()
			defer mu.Unlock()
			if _, ok := storage[arr[idx]]; !ok {
				storage[arr[idx]] = struct{}{}
				uniqueIds <- arr[idx]
			}
		}(i)
	}

	go func() {
		wg.Wait()
		close(uniqueIds)
	}()

	for v := range uniqueIds {
		fmt.Println("unique:", v)
	}
}

// ---------------- Context timeout around a long call ----------------

func longFunc() int {
	time.Sleep(time.Duration(rand.Intn(5)) * time.Second)
	return 200
}

func callingLongFunc(ctx context.Context) (int, error) {
	ch := make(chan int, 1)
	go func() {
		ch <- longFunc()
	}()

	select {
	case <-ctx.Done():
		return 0, errors.New("timeout")
	case v := <-ch:
		return v, nil
	}
}

func contextTimeoutEx() {
	ctx, cancel := context.WithTimeout(context.Background(), time.Second)
	defer cancel()
	res, err := callingLongFunc(ctx)
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Println("result:", res)
}

// ---------------- Concurrent map with RWMutex ----------------

func concurrentMapEx() {
	const writes = 1000
	storage := make(map[int]int, writes)
	var wg sync.WaitGroup
	var mu sync.RWMutex

	wg.Add(writes)
	for i := 0; i < writes; i++ {
		i := i
		go func() {
			defer wg.Done()
			mu.Lock()
			storage[i] = i
			mu.Unlock()
		}()
	}
	wg.Wait()

	wg.Add(writes)
	for i := 0; i < writes; i++ {
		i := i
		go func() {
			defer wg.Done()
			mu.RLock()
			_ = storage[i]
			mu.RUnlock()
		}()
	}
	wg.Wait()
	fmt.Println("map size:", len(storage))
}

// ---------------- Fan-in ----------------

func fanIn(ctx context.Context, chans []<-chan int) <-chan int {
	res := make(chan int)
	var wg sync.WaitGroup

	for _, ch := range chans {
		wg.Add(1)
		go func(c <-chan int) {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					return
				case v, ok := <-c:
					if !ok {
						return
					}
					select {
					case <-ctx.Done():
						return
					case res <- v:
					}
				}
			}
		}(ch)
	}

	go func() {
		wg.Wait()
		close(res)
	}()

	return res
}

// ---------------- Generic generator ----------------

func Generator[T any](ctx context.Context, data []T) <-chan T {
	res := make(chan T)
	go func() {
		defer close(res)
		for i := 0; i < len(data); i++ {
			select {
			case res <- data[i]:
			case <-ctx.Done():
				return
			}
		}
	}()
	return res
}

// ---------------- processData with context ----------------

func processData(v int) int {
	time.Sleep(time.Duration(rand.Intn(10)) * time.Second)
	return v * 5
}

func processDataWithContext(ctx context.Context, v int) int {
	ch := make(chan int, 1)
	go func() {
		ch <- processData(v)
	}()
	select {
	case <-ctx.Done():
		return 0
	case res := <-ch:
		return res
	}
}

// ---------------- Product of array except self ----------------
// [1, 2, 3] => [2*3, 1*3, 1*2] => [6, 3, 2]

func MultOther(in []int) []int {
	n := len(in)
	res := make([]int, n)
	if n == 0 {
		return res
	}

	// prefix products
	res[0] = 1
	for i := 1; i < n; i++ {
		res[i] = res[i-1] * in[i-1]
	}

	// suffix products folded in
	suffix := 1
	for i := n - 1; i >= 0; i-- {
		res[i] *= suffix
		suffix *= in[i]
	}

	return res
}

// ---------------- Bounded concurrent crawler (at most k in flight) ----------------

func get(url string) int {
	return 200
}

func crawl(urls []string, k int) []int {
	res := make([]int, len(urls))
	ch := make(chan int, k)
	var wg sync.WaitGroup

	go func() {
		defer close(ch)
		for i := range urls {
			ch <- i
		}
	}()

	for w := 0; w < k; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range ch {
				res[i] = get(urls[i])
			}
		}()
	}

	wg.Wait()
	return res
}

func main() {
	s := &Stack{}
	s.Push("a")
	s.Push("b")
	top, _ := s.Top()
	fmt.Println("stack top:", top)

	uniqueIdsEx()
	contextTimeoutEx()
	concurrentMapEx()

	fmt.Println("MultOther:", MultOther([]int{1, 2, 3}))

	urls := []string{"u1", "u2", "u3", "u4", "u5", "u6"}
	fmt.Println("crawl:", crawl(urls, 3))

	_ = fanIn
	_ = Generator[int]
	_ = processDataWithContext
}

package main

import (
	"fmt"
	"math"
)

type Shape interface {
	Area() float64
	Name() string
}

type Rectangle struct {
	Width  float64
	Height float64
}

func (r Rectangle) Area() float64 {
	return r.Width * r.Height
}

func (r Rectangle) Name() string {
	return "Rectangle"
}

type Circle struct {
	Radius float64
}

func (c Circle) Area() float64 {
	return math.Pi * c.Radius * c.Radius
}

func (c Circle) Name() string {
	return "Circle"
}

func NewShape(shapeType string, params ...float64) (Shape, error) {
	switch shapeType {
	case "rectangle":
		if len(params) != 2 {
			return nil, fmt.Errorf("rectangle requires 2 parameters: width and height")
		}
		return Rectangle{Width: params[0], Height: params[1]}, nil
	case "circle":
		if len(params) != 1 {
			return nil, fmt.Errorf("circle requires 1 parameter: radius")
		}
		return Circle{Radius: params[0]}, nil
	default:
		return nil, fmt.Errorf("unknown shape type: %s", shapeType)
	}
}

func PrintShapeInfo(s Shape) {
	fmt.Printf("Shape: %s, Area: %.2f\n", s.Name(), s.Area())
}

func main() {
	fmt.Println("--- Factory Pattern ---")

	rect, err := NewShape("rectangle", 10, 5)
	if err != nil {
		fmt.Println("Error:", err)
	} else {
		PrintShapeInfo(rect)
	}

	circ, err := NewShape("circle", 7)
	if err != nil {
		fmt.Println("Error:", err)
	} else {
		PrintShapeInfo(circ)
	}

	_, err = NewShape("triangle", 10)
	if err != nil {
		fmt.Println("Error creating shape:", err)
	}
}

package main

import (
	"fmt"
	"hash/fnv"
	"sync"
)

// 1. Интерфейс кеша
type Cache interface {
	Set(key, value string)
	Get(key string) (string, bool)
}

// 2. Структура одного шарда (map + RWMutex)
type shard struct {
	mu   sync.RWMutex
	data map[string]string
}

func newShard() *shard {
	return &shard{data: make(map[string]string)}
}

func (s *shard) Set(key, value string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.data[key] = value
}

func (s *shard) Get(key string) (string, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.data[key]
	return v, ok
}

// 3. Основная структура кеша с шардированием
type ShardedCache struct {
	shards []*shard
	n      int // количество шардов
}

func NewShardedCache(numShards int) *ShardedCache {
	shards := make([]*shard, numShards)
	for i := range shards {
		shards[i] = newShard()
	}
	return &ShardedCache{shards: shards, n: numShards}
}

// вспомогательная функция: вычисление номера шарда по ключу через FNV-хэш
func (c *ShardedCache) getShardIndex(key string) int {
	hash := fnv.New32a()
	hash.Write([]byte(key))
	return int(hash.Sum32()) % c.n
}

// реализуем методы интерфейса
func (c *ShardedCache) Set(key, value string) {
	idx := c.getShardIndex(key)
	c.shards[idx].Set(key, value)
}

func (c *ShardedCache) Get(key string) (string, bool) {
	idx := c.getShardIndex(key)
	return c.shards[idx].Get(key)
}

// 4. Пример теста с конкуренцией
func main() {
	cache := NewShardedCache(5)

	// Простейшая проверка
	cache.Set("foo", "bar")
	if v, ok := cache.Get("foo"); ok {
		fmt.Println("found:", v)
	} else {
		fmt.Println("not found")
	}

	// Проверка конкурентности - параллельно сетим и гетим
	var wg sync.WaitGroup
	keys := []string{"foo", "bar", "baz", "qux", "quux"}
	values := []string{"one", "two", "three", "four", "five"}

	// Set параллельно
	for i := 0; i < len(keys); i++ {
		wg.Add(1)
		go func(k, v string) {
			defer wg.Done()
			cache.Set(k, v)
		}(keys[i], values[i])
	}

	// Get параллельно
	for i := 0; i < len(keys); i++ {
		wg.Add(1)
		go func(k string) {
			defer wg.Done()
			v, ok := cache.Get(k)
			if ok {
				fmt.Printf("key:%s, value:%s\n", k, v)
			} else {
				fmt.Printf("key:%s, NOT found\n", k)
			}
		}(keys[i])
	}

	wg.Wait()
}

