func merge(cs ...<-chan int) <-chan int {
	res := make(chan int)
	var wg sync.WaitGroup
	for _, ch := range cs {
		wg.Add(1)
		go func(ch <-chan int) {
			defer wg.Done()
			for v := range ch {
				res <- v
			}
		}(ch)
	}
	go func() {
		wg.Wait()
		close(res)
	}()
	return res
}

