// -------------------------
// Generic concurrency patterns
// YouTube: https://www.youtube.com/watch?v=pgR9z5mWZmM

// Generator creates a channel that produces values from data
func Generator[T any](ctx context.Context, data []T) <-chan T {
	res := make(chan T)

	go func() {
		defer close(res)
		for i := 0; i < len(data); i++ {
			select {
			case <-ctx.Done():
				return
			case res <- data[i]:
			}
		}
	}()

	return res
}

// Start processes input data concurrently with multiple workers
// YouTube: https://www.youtube.com/watch?v=pgR9z5mWZmM
func Start[T, R any](ctx context.Context, input <-chan T, workerNum int, transform func(T) R) chan R {
	res := make(chan R)
	wg := new(sync.WaitGroup)

	for i := 0; i < workerNum; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					return
				case v, ok := <-input:
					if !ok {
						return
					}
					select {
					case <-ctx.Done():
						return
					case res <- transform(v):
					}
				}
			}
		}()
	}

	go func() {
		wg.Wait()
		close(res)
	}()

	return res
}

// -------------------------
// Fan-in pattern
// YouTube: https://www.youtube.com/watch?v=vMGCm0HvBgI

// fanIn combines multiple channels into one
func fanIn(ctx context.Context, chans []<-chan int) <-chan int {
	out := make(chan int)

	go func() {
		defer close(out)
		wg := &sync.WaitGroup{}
		for _, ch := range chans {
			wg.Add(1)
			go func(ch <-chan int) {
				defer wg.Done()
				for {
					select {
					case v, ok := <-ch:
						if !ok {
							return
						}
						select {
						case out <- v:
						case <-ctx.Done():
							return
						}
					case <-ctx.Done():
						return
					}
				}
			}(ch)
		}

		wg.Wait()
	}()

	return out
}

