}

// Worker pool pattern implementation
// YouTube: https://www.youtube.com/watch?v=qGca_8VldmE
func urlsMainWorkerPool() {
	urls := make([]string, 1000)
	codes := make(map[int]int)
	mu := sync.Mutex{}
	wg := sync.WaitGroup{}

	ch := make(chan string)

	go func() {
		defer close(ch)
		for _, url := range urls {
			ch <- url
		}
	}()

	wg.Add(5)
	for i := 0; i < 5; i++ {
		go func() {
			defer wg.Done()
			for url := range ch {
				code := sendReq(url)
				mu.Lock()
				codes[code]++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
}

// Semaphore pattern implementation
// YouTube: https://www.youtube.com/watch?v=v4EsDebU_es
func urlsMainSemaphore() {
	urls := make([]string, 1000)
	codes := make(map[int]int)
	mu := sync.Mutex{}
	wg := sync.WaitGroup{}
	sema := make(chan struct{}, 5)

	wg.Add(len(urls))
	for _, url := range urls {
		url := url // capture loop variable
		sema <- struct{}{}
		go func() {
			defer func() {
				<-sema
				wg.Done()
			}()
			code := sendReq(url)
			mu.Lock()
			codes[code]++
			mu.Unlock()
		}()
	}
	wg.Wait()
}

