// Panic recovery example
// YouTube: https://www.youtube.com/watch?v=pgR9z5mWZmM
func protect(g func()) {
	defer func() {
		fmt.Println("done")
		if x := recover(); x != nil {
			fmt.Printf("run time panic: %v\n", x)
		}
	}()

	fmt.Println("start")
	g()
}

func panicExample() {
	protect(func() {
		panic("test")
	})
	fmt.Println("all done")
}

// Context with timeout example
// YouTube: https://www.youtube.com/watch?v=Hy3KXGFyhwQ
func longFunc() int {
	time.Sleep(time.Duration(rand.Intn(5)) * time.Second)
	return 42
}

func callingLongFunc(ctx context.Context) (int, error) {
	ch := make(chan int, 1)

	go func() {
		defer close(ch)
		ch <- longFunc()
	}()

	select {
	case <-ctx.Done():
		return 0, errors.New("timeout")
	case v := <-ch:
		return v, nil
	}
}

func contextTimeoutExample() {
	ctx, cancel := context.WithTimeout(context.Background(), time.Second)
	defer cancel()

	result, err := callingLongFunc(ctx)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	fmt.Println("Result:", result)
}

// Unique numbers example
// YouTube: https://www.youtube.com/watch?v=wzluC-Suwk4
func uniqNum(n int) []int {
	m := make(map[int]bool)
	arr := make([]int, 0, n)

	for len(arr) < n {
		num := rand.Intn(1000)
		if !m[num] {
			m[num] = true
			arr = append(arr, num)
		}
	}
	return arr
}

// Concurrent map access with RWMutex
// YouTube: https://www.youtube.com/watch?v=aJ74a1gydbQ
func concurrentMapExample() {
	writes := 1000
	storage := make(map[int]int, writes)
	mu := sync.RWMutex{}
	wg := sync.WaitGroup{}

	wg.Add(writes)
	for i := 0; i < writes; i++ {
		i := i
		go func() {
			defer wg.Done()
			mu.Lock()
			storage[i] = i
			mu.Unlock()
		}()
	}
	wg.Wait()

	wg.Add(writes)
	for i := 0; i < writes; i++ {
		i := i
		go func() {
			defer wg.Done()
			mu.RLock()
			_, _ = storage[i]
			mu.RUnlock()
		}()
	}

	wg.Wait()
	fmt.Println("Map size:", len(storage))
}

// Unique IDs with concurrency
// YouTube: https://www.youtube.com/watch?v=U3fEaBDZvyE
func uniqueIDsExample() {
	rand.Seed(time.Now().UnixNano())

	alreadyStored := make(map[int]struct{})
	var mu sync.Mutex
	wg := sync.WaitGroup{}
	const capacity = 1000
	doubles := make([]int, 0, capacity)
	for i := 0; i < capacity; i++ {
		doubles = append(doubles, rand.Intn(10))
	}
	uniqueIds := make(chan int, capacity)

	for i := 0; i < capacity; i++ {
		i := i
		wg.Add(1)
		go func() {
			defer wg.Done()
			mu.Lock()
			defer mu.Unlock()
			if _, ok := alreadyStored[doubles[i]]; !ok {
				alreadyStored[doubles[i]] = struct{}{}
				uniqueIds <- doubles[i]
			}
		}()
	}
	go func() {
		wg.Wait()
		close(uniqueIds)
	}()
	for v := range uniqueIds {
		fmt.Println("u: ", v)
	}
}

// -------------
// Stack
// YouTube: https://www.youtube.com/watch?v=o5IB0E3z-wo

type Stack struct {
	items []string
}

func (s *Stack) Push(data string) {
	s.items = append(s.items, data)
}

func (s *Stack) Pop() {
	if s.isEmpty() {
		return
	}
	s.items = s.items[:len(s.items)-1]
}

func (s *Stack) isEmpty() bool {
	return len(s.items) == 0
}

func (s *Stack) Top() (string, error) {
	if s.isEmpty() {
		return "", fmt.Errorf("error")
	}
	return s.items[len(s.items)-1], nil
}

// -------------
// Pipeline: generator -> square
// https://www.youtube.com/watch?v=...

func genPipe(ctx context.Context, nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for _, v := range nums {
			select {
			case <-ctx.Done():
				return
			case out <- v:
			}
		}
	}()
	return out
}

func sq(ctx context.Context, in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for i := range in {
			i := i
			result := func() int {
				time.Sleep(100 * time.Millisecond)
				return i * i
			}()
			select {
			case <-ctx.Done():
				return
			case out <- result:
			}
		}
	}()
	return out
}

func pipelineExample() {
	ctx, cancel := context.WithTimeout(context.Background(), 400*time.Millisecond)
	defer cancel()
	for val := range sq(ctx, genPipe(ctx, 1, 2, 3, 4, 5)) {
		fmt.Println(val)
	}
}
